-- Records of RSK_ISUP_INDICATOR_PARA_DTL
-- --------------------------------------
delete from RSK_ISUP_INDICATOR_PARA_DTL; 
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('NHGZJYE', '04', 'SQL', 'select sum(TRADE_AMT) as tradeAmt from	 
(	 
  select 	 
	sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)) as  TRADE_AMT from PTL_SEC_VALUTION m 
  INNER JOIN FIN_TRADE_PRODUCT n on m.FINPROD_ID = n.FINPROD_ID and n.FINPROD_TYPE2 in (''F03'',''F05'') AND n.BRANCH=0	 
  where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}''-1	 
	 
union ALL	 
  select	 
  nvl(sum(decode(n.PS,''T01'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 
  -nvl(sum(decode(n.PS,''T07'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) as TRADE_AMT  from TRD_PRODUCT_DEAL_ADD m	 
  inner join TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID	 
  INNER JOIN FIN_TRADE_PRODUCT t2 on t2.FINPROD_ID=n.FINPROD_ID and t2.FINPROD_TYPE2 in (''F03'',''F05'') AND t2.BRANCH=0	 
  where m.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T01'',''T07'')	 
	 
union ALL	 
  select	 
  nvl(sum(decode(n.PS,''T01'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 
  -nvl(sum(decode(n.PS,''T07'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) as  TRADE_AMT  from WFL_TRD_PRODUCT_DEAL_ADD m	 
  inner join WFL_TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID and n.TRADE_STATUS != ''03''	 
  INNER JOIN WFL_PA_TRD_PRODUCT_DEAL t2 on t2.TRADE_ID=n.TRADE_ID and t2.PA_BUSS_TYPE in (''19'',''75'')	 
  where m.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T01'',''T07'') 	 
)', 'portfolioCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:26', 'jjpei', TIMESTAMP '2020-05-05 14:23:26');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('NHGZJYE', '05', 'SQL', 'select 	
  nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)),0) as  TRADE_AMT from PTL_SEC_VALUTION m	
INNER JOIN FIN_TRADE_PRODUCT n on m.FINPROD_ID = n.FINPROD_ID and n.FINPROD_TYPE2 in (''F03'',''F05'') AND n.BRANCH=0	
where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}''', 'portfolioCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:26', 'jjpei', TIMESTAMP '2020-05-05 14:23:26');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('DYGLF', '03', 'SQL', 'with temp as (select  m.FINPROD_ID,m.FINPROD_TYPE2,
case when m.FINPROD_TYPE2 = ''F01'' then m.ISSUER else m.FINANCIER end org_code
FROM
    FIN_PRODUCT m
INNER JOIN
    FIN_PRODUCT_TYPE fpt ON  m.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0
AND (  (fpt.TYPE_8 =''F06'' and fpt.TYPE_6 IN(''P01'',''P11'')) OR  ( fpt.TYPE_8 =''F01''  AND fpt.TYPE_6 =''B18'')))

SELECT RKEY,SUM(RVALUE) RVALUE FROM (
SELECT nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)),0) as  RVALUE
, m.PORTFOLIO_ID||'',''||g.org_code as RKEY from PTL_SEC_VALUTION m
 inner join (
 select FINPROD_ID,org_code,org_code org_code_union from temp
 union all
 select DISTINCT c.FINPROD_ID,a.org_code,b.COR_ORGID org_code_union from  temp a
 inner join INF_ORG_CORRELATION b on a.org_code = b.ORG_NO
 inner join temp c on c.org_code = b.COR_ORGID
 ) g on  m.FINPROD_ID=g.FINPROD_ID
where    m.CDATE =date''${valDate}''-1  group by m.PORTFOLIO_ID,g.org_code
 union all
   select sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)) as RVALUE, s2.PTL_BAG_ID||'',''||s1.org_code as RKEY
   FROM ( select m.*,g.org_code from PTL_SEC_VALUTION m
   inner join (
 select FINPROD_ID,org_code,org_code org_code_union from temp
 union all
 select DISTINCT c.FINPROD_ID,a.org_code,b.COR_ORGID org_code_union from  temp a
 inner join INF_ORG_CORRELATION b on a.org_code = b.ORG_NO
 inner join temp c on c.org_code = b.COR_ORGID
 ) g on  m.FINPROD_ID=g.FINPROD_ID
  where  m.CDATE =date''${valDate}''-1 ) s1,( select t1.PORTFOLIO_ID,t1.PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' )
    s2 where s1.PORTFOLIO_ID=s2.PORTFOLIO_ID  group by s2.PTL_BAG_ID,s1.org_code
) GROUP BY RKEY', 'portfolioCode,issuerCode', 'N', 'GY', '001', TIMESTAMP '2020-05-14 17:29:05', 'GY', TIMESTAMP '2020-05-14 17:29:05');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('DYGLF', '01', 'SQL', 'with temp as (select  m.FINPROD_ID,m.FINPROD_TYPE2,
