   select t.PTL_BAG_ID as RKEY,		 
   ( select nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)),0) as  RVALUE from PTL_SEC_VALUTION m		 
