   )		 
   from RSK_PORTFOLIO_PACKAGE t', 'portfolioCode', 'Y', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:28', 'jjpei', TIMESTAMP '2020-05-05 14:23:28');
