INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('CPZCLZCGM', '05', 'SQL', 'select sum(TRADE_AMT) as tradeAmt from		
 (		
select nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)),0) as TRADE_AMT from PTL_SEC_VALUTION m		
  INNER JOIN FIN_PRODUCT_ADD PFP		
  on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''01''		
   LEFT JOIN FIN_PRODUCT_TYPE FPT ON m.FINPROD_ID=FPT.FINPROD_ID AND FPT.BRANCH=0		
where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}'' AND m.PORTFOLIO_ID!=m.FINPROD_ID		
union all		
select		
  sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)) as  TRADE_AMT from PTL_SEC_VALUTION m		
INNER JOIN FIN_TRADE_PRODUCT n on m.FINPROD_ID = n.FINPROD_ID and n.FINPROD_TYPE2 in (''F03'',''F05'',''F09'') AND n.BRANCH=0		
where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}''		
)', 'portfolioCode', 'N', 'GY', '001', TIMESTAMP '2020-05-13 10:28:24', 'GY', TIMESTAMP '2020-05-13 10:28:24');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('XJGZZYYHPJZCXJRZQGM', '05', 'SQL', 'select sum(TRADE_AMT) as tradeAmt from	
(	
  select nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)),0) as  TRADE_AMT from PTL_SEC_VALUTION m	
  INNER JOIN FIN_PRODUCT n on m.FINPROD_ID=n.FINPROD_ID and n.FINPROD_TYPE2 =''F01'' and n.MDATE>=date''${valDate}'' and n.MDATE<=add_months(date''${valDate}'', 12)	
  inner join FIN_PRODUCT_TYPE t3 on n.FINPROD_ID=t3.FINPROD_ID and (t3.TYPE_6 in (''B01'',''B03'') or (t3.TYPE_6=''B05'' AND t3.TYPE_7=''01''))  and t3.TYPE_8 =''F01''	
  where  m.PORTFOLIO_ID in ${portfolioCode}  and m.CDATE=date''${valDate}''	
)', 'portfolioCode', 'N', 'GY', '001', TIMESTAMP '2020-05-13 11:11:41', 'GY', TIMESTAMP '2020-05-13 11:11:41');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('DYGLF', '02', 'SQL', 'with temp as (select  m.FINPROD_ID,m.FINPROD_TYPE2,
case when m.FINPROD_TYPE2 = ''F01'' then m.ISSUER else m.FINANCIER end org_code
FROM
    FIN_PRODUCT m
INNER JOIN
    FIN_PRODUCT_TYPE fpt ON  m.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0
AND (  (fpt.TYPE_8 =''F06'' and fpt.TYPE_6 IN(''P01'',''P11'')) OR  ( fpt.TYPE_8 =''F01''  AND fpt.TYPE_6 =''B18'')))

SELECT RKEY,SUM(RVALUE) RVALUE FROM (
SELECT nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)),0) as  RVALUE
, m.PORTFOLIO_ID||'',''||g.org_code as RKEY from PTL_SEC_VALUTION m
 inner join (
 select FINPROD_ID,org_code,org_code org_code_union from temp
 union all
 select DISTINCT c.FINPROD_ID,a.org_code,b.COR_ORGID org_code_union from  temp a
 inner join INF_ORG_CORRELATION b on a.org_code = b.ORG_NO
 inner join temp c on c.org_code = b.COR_ORGID
 ) g on  m.FINPROD_ID=g.FINPROD_ID
where    m.CDATE =date''${valDate}''-1  group by m.PORTFOLIO_ID,g.org_code
 union all
   select sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)) as RVALUE, s2.PTL_BAG_ID||'',''||s1.org_code as RKEY
   FROM ( select m.*,g.org_code from PTL_SEC_VALUTION m
   inner join (
 select FINPROD_ID,org_code,org_code org_code_union from temp
 union all
 select DISTINCT c.FINPROD_ID,a.org_code,b.COR_ORGID org_code_union from  temp a
 inner join INF_ORG_CORRELATION b on a.org_code = b.ORG_NO
 inner join temp c on c.org_code = b.COR_ORGID
 ) g on  m.FINPROD_ID=g.FINPROD_ID
  where  m.CDATE =date''${valDate}''-1 ) s1,( select t1.PORTFOLIO_ID,t1.PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' )
    s2 where s1.PORTFOLIO_ID=s2.PORTFOLIO_ID  group by s2.PTL_BAG_ID,s1.org_code
) GROUP BY RKEY', 'portfolioCode,issuerCode', 'N', 'GY', '001', TIMESTAMP '2020-05-14 17:29:05', 'GY', TIMESTAMP '2020-05-14 17:29:05');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('SSGSKLTGB', '05', 'SQL', 'SELECT RVALUE,RKEY,RKEYCN FROM (		
	SELECT (SELECT nvl(sum(s.C_SHARES),0) FROM MST_SHARE_PRICE s WHERE s.SHARES_ID=t2.FINPROD_MARKET_ID AND s.DEAL_DATE=(	
		SELECT max(DEAL_DATE) FROM MST_SHARE_PRICE m WHERE m.SHARES_ID=t2.FINPROD_MARKET_ID and m.DEAL_DATE<=date''${valDate}'')
	) AS RVALUE,	
    T2.FINPROD_ID RKEY,		
	t2.FINPROD_NAME RKEYCN FROM PTL_SEC_VALUTION T1 	
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID 	
	inner join FIN_PRODUCT_TYPE fpt on t1.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 and (fpt.TYPE_8 =''F11''  OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B17''))	
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND t1.CDATE=date''${valDate}''	
	)', 'assetCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:25', 'jjpei', TIMESTAMP '2020-05-05 14:23:25');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('SONDZGMZCGLZTZQ', '03', 'SQL', 'SELECT nvl(t2.ISSUE_AMT,0)*nvl(BOND.PRICE,100)/100 AS RVALUE,	
T2.FINPROD_ID RKEY FROM  FIN_PRODUCT t2	
LEFT JOIN (	
    SELECT SEC_ID,nvl(PRICE,100) PRICE FROM (SELECT SEC_ID,PRICE, RANK() OVER(PARTITION BY SEC_ID ORDER BY VALUE_DATE DESC ) AS rowno	
	FROM MST_BOND_VALUATION_INFO WHERE VALUE_DATE<=date''${valDate}'') WHERE rowno=1
) BOND ON t2.FINPROD_MARKET_ID=BOND.SEC_ID	
WHERE T2.FINPROD_TYPE2 =''F01''', 'portfolioCode,assetCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:25', 'jjpei', TIMESTAMP '2020-05-05 14:23:25');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('SSGSKLTGB', '04', 'SQL', 'SELECT DISTINCT RVALUE,RKEY,RKEYCN FROM (		 
	SELECT RVALUE,RKEY,RKEYCN FROM (	 
	SELECT (SELECT nvl(sum(s.C_SHARES),0) FROM MST_SHARE_PRICE s WHERE s.SHARES_ID=t2.FINPROD_MARKET_ID AND s.DEAL_DATE=(	 
		SELECT max(DEAL_DATE) FROM MST_SHARE_PRICE m WHERE m.SHARES_ID=t2.FINPROD_MARKET_ID and m.DEAL_DATE<=date''${valDate}'') 
	) AS RVALUE,	 
    T2.FINPROD_ID RKEY,		 
	t2.FINPROD_NAME RKEYCN FROM PTL_SEC_VALUTION T1	 
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID 	 
	inner join FIN_PRODUCT_TYPE fpt on t1.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 and (fpt.TYPE_8 =''F11''  OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B17''))	 
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND t1.CDATE=date''${valDate}''-1	 
	)	 
UNION ALL		 
	SELECT RVALUE,RKEY,RKEYCN FROM (	 
	SELECT (SELECT nvl(sum(s.C_SHARES),0) FROM MST_SHARE_PRICE s WHERE s.SHARES_ID=t2.FINPROD_MARKET_ID AND s.DEAL_DATE=(	 
		SELECT max(DEAL_DATE) FROM MST_SHARE_PRICE m WHERE m.SHARES_ID=t2.FINPROD_MARKET_ID and m.DEAL_DATE<=date''${valDate}'') 
	) AS RVALUE,	 
    T2.FINPROD_ID RKEY,		 
	t2.FINPROD_NAME RKEYCN FROM TRD_PRODUCT_DEAL t1	 
	INNER JOIN TRD_PRODUCT_DEAL_ADD n1 ON t1.TRADE_ID =n1.TRADE_ID	 
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID 	 
	inner join FIN_PRODUCT_TYPE fpt on t1.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 and (fpt.TYPE_8 =''F11''  OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B17''))	 
	WHERE n1.PORTFOLIO_ID IN ${portfolioCode} AND t1.TRADE_DATE=date''${valDate}''	 
	)	 
UNION ALL		 
	SELECT RVALUE,RKEY,RKEYCN FROM (	 
	SELECT (SELECT nvl(sum(s.C_SHARES),0) FROM MST_SHARE_PRICE s WHERE s.SHARES_ID=t2.FINPROD_MARKET_ID AND s.DEAL_DATE=(	 
		SELECT max(DEAL_DATE) FROM MST_SHARE_PRICE m WHERE m.SHARES_ID=t2.FINPROD_MARKET_ID and m.DEAL_DATE<=date''${valDate}'') 
	) AS RVALUE,	 
    T2.FINPROD_ID RKEY,		 
	t2.FINPROD_NAME RKEYCN FROM WFL_TRD_PRODUCT_DEAL_ADD t1	 
	inner join WFL_TRD_PRODUCT_DEAL n on t1.TRADE_ID=n.TRADE_ID and n.TRADE_STATUS != ''03''	 
	INNER JOIN FIN_PRODUCT t2 ON n.FINPROD_ID=t2.FINPROD_ID 	 
	inner join FIN_PRODUCT_TYPE fpt on n.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 and (fpt.TYPE_8 =''F11''  OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B17''))	 
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND n.TRADE_DATE=date''${valDate}''	 
	)	 
) S1', 'assetCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:25', 'jjpei', TIMESTAMP '2020-05-05 14:23:25');
