T2.FINPROD_ID RKEY FROM  FIN_PRODUCT t2	
LEFT JOIN (	
    SELECT SEC_ID,nvl(PRICE,100) PRICE FROM (SELECT SEC_ID,PRICE, RANK() OVER(PARTITION BY SEC_ID ORDER BY VALUE_DATE DESC ) AS rowno	
	FROM MST_BOND_VALUATION_INFO WHERE VALUE_DATE<=date''${valDate}'') WHERE rowno=1
) BOND ON t2.FINPROD_MARKET_ID=BOND.SEC_ID	
WHERE T2.FINPROD_TYPE2 =''F01''', 'assetCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:25', 'jjpei', TIMESTAMP '2020-05-05 14:23:25');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('GZQSZHZZQTZJJSZ', '01', 'SQL', 'SELECT S1.RVALUE,S1.RKEY FROM (		
		SELECT nvl(t2.ISSUE_AMT,0)*nvl(BOND.PRICE,100)/100 AS RVALUE,
		T2.FINPROD_ID RKEY FROM  FIN_PRODUCT t2
		LEFT JOIN (
	    SELECT SEC_ID,nvl(PRICE,100) PRICE FROM (SELECT SEC_ID,PRICE, RANK() OVER(PARTITION BY SEC_ID ORDER BY VALUE_DATE DESC ) AS rowno	
		FROM MST_BOND_VALUATION_INFO WHERE VALUE_DATE<=date''${valDate}'') WHERE rowno=1
		) BOND ON t2.FINPROD_MARKET_ID=BOND.SEC_ID
		WHERE T2.FINPROD_TYPE2 =''F01'' 
UNION ALL		
	SELECT RVALUE,RKEY FROM (	
		SELECT nvl(sum(JIJING.tradeAmount),0) RVALUE,
		T2.FINPROD_ID RKEY FROM FIN_PRODUCT t2
		LEFT JOIN (
		SELECT FINPROD_ID,nvl(VALUATION,1)*nvl(C_SHARES,0) AS tradeAmount FROM 	
		 	(	
		 	    SELECT s1.FINPROD_ID,CASE s2.TYPE_6 WHEN ''F01'' THEN 1 else VALUATION END VALUATION,C_SHARES, RANK() OVER(PARTITION BY s1.FINPROD_ID ORDER BY s1.VAL_DATE DESC ) AS rowno	
				FROM FIN_PRODUCT_VALUATION s1
				LEFT JOIN (SELECT m1.FINPROD_MARKET_ID,m2.TYPE_6 FROM FIN_PRODUCT m1 INNER JOIN FIN_PRODUCT_TYPE m2 ON m1.FINPROD_ID=m2.FINPROD_ID AND m2.BRANCH=0 AND m2.TYPE_8=''F02'') s2
				ON s1.FINPROD_ID=s2.FINPROD_MARKET_ID
				WHERE s1.VAL_DATE<=date''${valDate}''
			) WHERE rowno=1	
		) JIJING ON t2.FINPROD_MARKET_ID=JIJING.FINPROD_ID
		WHERE  T2.FINPROD_TYPE2 =''F06'' GROUP BY T2.FINPROD_ID,T2.FINPROD_MARKET_ID
	) group by RVALUE,RKEY	
UNION ALL		
	SELECT RVALUE,RKEY FROM (	
		SELECT (SELECT nvl(s.C_SHARES,0)*nvl(s.CLOSE_PRICE,0) FROM MST_SHARE_PRICE s WHERE s.SHARES_ID=t2.FINPROD_MARKET_ID AND s.DEAL_DATE=(
		SELECT max(DEAL_DATE) FROM MST_SHARE_PRICE m WHERE m.SHARES_ID=t2.FINPROD_MARKET_ID and m.DEAL_DATE<=date''${valDate}'')
	) AS RVALUE,	
		T2.FINPROD_ID RKEY FROM FIN_PRODUCT t2
		WHERE  T2.FINPROD_TYPE2 =''F10'' GROUP BY T2.FINPROD_ID,T2.FINPROD_MARKET_ID
	) group by RVALUE,RKEY	
) S1', 'assetCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:24', 'jjpei', TIMESTAMP '2020-05-05 14:23:24');
 
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('GZQSZHZZQTZJJSZ', '05', 'SQL', 'SELECT DISTINCT RVALUE,RKEY,RKEYCN FROM (		
	SELECT nvl(t2.ISSUE_AMT,0)*nvl(BOND.PRICE,100)/100 AS RVALUE,	
	T2.FINPROD_ID RKEY,t2.FINPROD_NAME RKEYCN FROM PTL_SEC_VALUTION T1	
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F01''	
	LEFT JOIN (	
	    SELECT SEC_ID,nvl(PRICE,100) PRICE FROM (SELECT SEC_ID,PRICE, RANK() OVER(PARTITION BY SEC_ID ORDER BY VALUE_DATE DESC ) AS rowno	
		FROM MST_BOND_VALUATION_INFO WHERE VALUE_DATE<=date''${valDate}'') WHERE rowno=1
	) BOND ON t2.FINPROD_MARKET_ID=BOND.SEC_ID	
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND t1.CDATE=date''${valDate}''	
UNION ALL		
	SELECT RVALUE,RKEY,RKEYCN FROM (	
	SELECT JIJING.tradeAmount RVALUE,	
    T2.FINPROD_ID RKEY,		
	t2.FINPROD_NAME RKEYCN FROM PTL_SEC_VALUTION T1	
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F06''	
	LEFT JOIN (	
	  SELECT FINPROD_ID,nvl(VALUATION,1)*nvl(C_SHARES,0) AS tradeAmount FROM 	
		 	(	
		 	    SELECT s1.FINPROD_ID,CASE s2.TYPE_6 WHEN ''F01'' THEN 1 else VALUATION END VALUATION,C_SHARES, RANK() OVER(PARTITION BY s1.FINPROD_ID ORDER BY s1.VAL_DATE DESC ) AS rowno	
				FROM FIN_PRODUCT_VALUATION s1
				LEFT JOIN (SELECT m1.FINPROD_MARKET_ID,m2.TYPE_6 FROM FIN_PRODUCT m1 INNER JOIN FIN_PRODUCT_TYPE m2 ON m1.FINPROD_ID=m2.FINPROD_ID AND m2.BRANCH=0 AND m2.TYPE_8=''F02'') s2
				ON s1.FINPROD_ID=s2.FINPROD_MARKET_ID
				WHERE s1.VAL_DATE<=date''${valDate}''
			) WHERE rowno=1	
	) JIJING ON t2.FINPROD_MARKET_ID=JIJING.FINPROD_ID	
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND t1.CDATE=date''${valDate}''	
	)	
UNION ALL		
	SELECT RVALUE,RKEY,RKEYCN FROM (	
	SELECT (SELECT nvl(s.C_SHARES,0)*nvl(s.CLOSE_PRICE,0) FROM MST_SHARE_PRICE s WHERE s.SHARES_ID=t2.FINPROD_MARKET_ID AND s.DEAL_DATE=(	
		SELECT max(DEAL_DATE) FROM MST_SHARE_PRICE m WHERE m.SHARES_ID=t2.FINPROD_MARKET_ID and m.DEAL_DATE<=date''${valDate}'')
	) AS RVALUE,	
    T2.FINPROD_ID RKEY,		
	t2.FINPROD_NAME RKEYCN FROM PTL_SEC_VALUTION T1	
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F10''	
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND t1.CDATE=date''${valDate}''	
	)	
) S1', 'assetCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:24', 'jjpei', TIMESTAMP '2020-05-05 14:23:24');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('AZZCJZJQDZHJQ', '05', 'SQL', 'SELECT sum((TRADE_AMT)*(M_DURATION)) AS jiuqi FROM (select				 
	A1.TRADE_AMT,			 
	A1.mdate,			 
	CASE WHEN A1.FINPROD_TYPE =''F01'' THEN			 
	(			 
		select CASE WHEN nvl(sum(B1.M_DURATION),0)=0 THEN (((A1.mdate)-(date''${valDate}''))/365) ELSE (nvl(sum(B1.M_DURATION),0)) END M_DURATION from  MST_BOND_VALUATION_INFO B1		 
	    inner join			 
	    (select to_char(max(VALUE_DATE),''yyyy-MM-dd'') as VALUE_DATE,SEC_ID from MST_BOND_VALUATION_INFO where VALUE_DATE<=date''${valDate}'' group by sec_id) B2			 
	    on B1.SEC_ID=B2.SEC_ID and to_char(B1.VALUE_DATE,''yyyy-MM-dd'') =B2.VALUE_DATE WHERE B1.SEC_ID=A1.FINPROD_ID			 
	)			 
WHEN (A1.FINPROD_TYPE =''F06'' OR A1.FINPROD_TYPE =''XJ'') THEN (1)/365		
WHEN (A1.FINPROD_TYPE =''F10'' AND A1.MDATE IS NULL) THEN (1) 		 
WHEN a1.FINPROD_ID =a1.PORTFOLIO_ID	THEN (1)/365			 
ELSE ((((A1.mdate)-(date''${valDate}'')))/365) END M_DURATION				 
from				 
(				 
    select NULL AS FINPROD_ID,NULL AS PORTFOLIO_ID,nvl(sum(AMOUNT),0) as  TRADE_AMT,''XJ'' AS FINPROD_TYPE,NULL AS MDATE   from PTL_CASH_POSITION				 
 	 where  PORTFOLIO_ID in ${portfolioCode} and HODING_TYPE=''03'' and CDATE =date''${valDate}''			 
    UNION ALL				 
	select			 
	t2.FINPROD_MARKET_ID FINPROD_ID,t1.PORTFOLIO_ID,nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0) as TRADE_AMT,t2.FINPROD_TYPE2,t2.MDATE			 
	from PTL_SEC_VALUTION t1			 
	 inner join FIN_PRODUCT t2	on t1.FINPROD_ID = t2.FINPROD_ID		 
	where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE = date''${valDate}''	
      and t2.FINPROD_TYPE2 not in (''F10'',''F15'',''F11'',''F12'',''F13'',''F35'',''F14'') 	
    UNION ALL				 
    select				 
	NVL(t2.FINPROD_MARKET_ID,t1.FINPROD_ID) FINPROD_ID,t1.PORTFOLIO_ID,nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0) as TRADE_AMT,t3.FINPROD_TYPE2,t3.MDATE			 
	from PTL_SEC_VALUTION t1			 
	inner join FIN_TRADE_PRODUCT t3	 on t1.FINPROD_ID = t3.FINPROD_ID AND t3.BRANCH=0	
    left join FIN_PRODUCT t2 on t3.FINPROD_ID = t2.FINPROD_ID	
	where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE = date''${valDate}''			 
	and t3.FINPROD_TYPE2 not in (''F02'',''F04'',''F08'', ''F25'',''F10'',''F15'',''F11'',''F12'',''F13'',''F35'',''F14'')			 
) A1				 
)', 'portfolioCode', 'N', 'GY', '001', TIMESTAMP '2020-05-09 14:56:09', 'GY', TIMESTAMP '2020-05-09 14:56:09');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('GZQSZHZZQTZJJSZ', '02', 'SQL', 'SELECT S1.RVALUE,S1.RKEY FROM (		
		SELECT nvl(t2.ISSUE_AMT,0)*nvl(BOND.PRICE,100)/100 AS RVALUE,
		T2.FINPROD_ID RKEY FROM  FIN_PRODUCT t2
		LEFT JOIN (
	    SELECT SEC_ID,nvl(PRICE,100) PRICE FROM (SELECT SEC_ID,PRICE, RANK() OVER(PARTITION BY SEC_ID ORDER BY VALUE_DATE DESC ) AS rowno	
		FROM MST_BOND_VALUATION_INFO WHERE VALUE_DATE<=date''${valDate}'') WHERE rowno=1
		) BOND ON t2.FINPROD_MARKET_ID=BOND.SEC_ID
		WHERE T2.FINPROD_TYPE2 =''F01'' 
UNION ALL		
	SELECT RVALUE,RKEY FROM (	
		SELECT nvl(sum(JIJING.tradeAmount),0) RVALUE,
		T2.FINPROD_ID RKEY FROM FIN_PRODUCT t2
		LEFT JOIN (
		SELECT FINPROD_ID,nvl(VALUATION,1)*nvl(C_SHARES,0) AS tradeAmount FROM 	
		 	(	
		 	    SELECT s1.FINPROD_ID,CASE s2.TYPE_6 WHEN ''F01'' THEN 1 else VALUATION END VALUATION,C_SHARES, RANK() OVER(PARTITION BY s1.FINPROD_ID ORDER BY s1.VAL_DATE DESC ) AS rowno	
				FROM FIN_PRODUCT_VALUATION s1
				LEFT JOIN (SELECT m1.FINPROD_MARKET_ID,m2.TYPE_6 FROM FIN_PRODUCT m1 INNER JOIN FIN_PRODUCT_TYPE m2 ON m1.FINPROD_ID=m2.FINPROD_ID AND m2.BRANCH=0 AND m2.TYPE_8=''F02'') s2
				ON s1.FINPROD_ID=s2.FINPROD_MARKET_ID
				WHERE s1.VAL_DATE<=date''${valDate}''
			) WHERE rowno=1	
		) JIJING ON t2.FINPROD_MARKET_ID=JIJING.FINPROD_ID
		WHERE  T2.FINPROD_TYPE2 =''F06'' GROUP BY T2.FINPROD_ID,T2.FINPROD_MARKET_ID
	) group by RVALUE,RKEY	
UNION ALL		
	SELECT RVALUE,RKEY FROM (	
		SELECT (SELECT nvl(s.C_SHARES,0)*nvl(s.CLOSE_PRICE,0) FROM MST_SHARE_PRICE s WHERE s.SHARES_ID=t2.FINPROD_MARKET_ID AND s.DEAL_DATE=(
		SELECT max(DEAL_DATE) FROM MST_SHARE_PRICE m WHERE m.SHARES_ID=t2.FINPROD_MARKET_ID and m.DEAL_DATE<=date''${valDate}'')
	) AS RVALUE,	
		T2.FINPROD_ID RKEY FROM FIN_PRODUCT t2
		WHERE  T2.FINPROD_TYPE2 =''F10'' GROUP BY T2.FINPROD_ID,T2.FINPROD_MARKET_ID
	) group by RVALUE,RKEY	
) S1', 'assetCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:24', 'jjpei', TIMESTAMP '2020-05-05 14:23:24');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('CPJZCJZ', '05', 'SQL', 'SELECT NVL(SUM(TDY_ASSET_NETVALUE),0) AS amount		
FROM PTL_PORTFOLIO_VALUATION		
WHERE PORTFOLIO_ID IN ${portfolioCode} AND CDATE = date''${valDate}''', 'portfolioCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:21', 'jjpei', TIMESTAMP '2020-05-05 14:23:21');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('CPJZCJZ', '01', 'SQL', 'WITH  temp  as(			 
  SELECT 			 
       DISTINCT t2.PORTFOLIO_ID ,			 
       mujiData.mujiAmt  as AMOUNT			 
       from  PTL_PORTFOLIO t2			 
       left join 			 
       (			 
       select t1.PORTFOLIO_ID, sum(t1.TRADE_AMT) as mujiAmt from TRD_FIN_PRODUCT_DEAL_TOTAL t1			 
       WHERE  t1.PS in (''C1'', ''C2'')	 and t1.SETTLE_DATE <= date''${valDate}'' and t1.TRADE_STATUS=''01''		 
       group by t1.PORTFOLIO_ID			 
       ) mujiData			 
       on t2.PORTFOLIO_ID = mujiData.PORTFOLIO_ID			 
       where  t2.VDATE=date''${valDate}''			 
 UNION ALL			 
      SELECT 			 
       DISTINCT t1.PORTFOLIO_ID RKEY,			 
        nvl(TDY_ASSET_NETVALUE,0) as RVALUE			 
       from PTL_PORTFOLIO_VALUATION t1			 
       where  t1.CDATE=date''${valDate}''-1 			 
 )			 
 SELECT PORTFOLIO_ID RKEY,AMOUNT RVALUE FROM temp			 
union all			 
   select m.PTL_BAG_ID as RKEY,		 	 
   (		 	 
        SELECT sum(AMOUNT) FROM ( 			 
          SELECT PORTFOLIO_ID,AMOUNT FROM temp			 
	   	 ) t1 where t1.PORTFOLIO_ID in (select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1	  
	     inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=m.PTL_BAG_ID)		 
   ) AS RVALUE		 	 
   from RSK_PORTFOLIO_PACKAGE m', 'portfolioCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:21', 'jjpei', TIMESTAMP '2020-05-05 14:23:21');
