INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('ZQDYWDDSYLQX', '02', 'SQL', 'SELECT FP.FINPROD_ID RKEY,IC.B_ANAL_YIELD RVALUE  
FROM FIN_PRODUCT FP 
inner JOIN INTERF_CBONDCURVECNBD IC ON IC.OBJECT_ID=FP.FINPROD_MARKET_ID 
LEFT JOIN (SELECT MAX(to_date(TRADE_DT,''yyyy-MM-dd'')) AS TRADE_DT, 
            OBJECT_ID 
            FROM INTERF_CBONDCURVECNBD 
            WHERE to_date(TRADE_DT,''yyyy-MM-dd'')<Date''${valDate}'' - 7 
            GROUP BY OBJECT_ID 
            ) ICN 
ON IC.OBJECT_ID                 =ICN.OBJECT_ID 
AND to_date(IC.TRADE_DT,''yyyy-MM-dd'')=ICN.TRADE_DT 
WHERE FP.FINPROD_TYPE2=''F01''', 'assetCode', 'N', 'whmcp', '2222222', TIMESTAMP '2020-05-05 14:23:22', 'whmcp', TIMESTAMP '2020-05-05 14:23:22');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('ZQDYWDDSYLQX', '05', 'SQL', 'SELECT FP.FINPROD_ID RKEY,IC.B_ANAL_YIELD RVALUE  
FROM FIN_PRODUCT FP 
inner JOIN INTERF_CBONDCURVECNBD IC ON IC.OBJECT_ID=FP.FINPROD_MARKET_ID 
LEFT JOIN (SELECT MAX(to_date(TRADE_DT,''yyyy-MM-dd'')) AS TRADE_DT, 
            OBJECT_ID 
            FROM INTERF_CBONDCURVECNBD 
            WHERE to_date(TRADE_DT,''yyyy-MM-dd'')<Date''${valDate}'' - 7 
            GROUP BY OBJECT_ID 
            ) ICN 
ON IC.OBJECT_ID                 =ICN.OBJECT_ID 
AND to_date(IC.TRADE_DT,''yyyy-MM-dd'')=ICN.TRADE_DT 
WHERE FP.FINPROD_TYPE2=''F01''', 'assetCode', 'N', 'whmcp', '2222222', TIMESTAMP '2020-05-05 14:23:22', 'whmcp', TIMESTAMP '2020-05-05 14:23:22');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('ZHGSYQX', '04', 'SQL', 'SELECT (nvl(sum(TRADE_AMT*LAST_PERIOD),0)) AS lastPeriod FROM ( 
  select 
	DISTINCT TRADE_AMT, 
	 nvl((A1.mdate)-(date''${valDate}''),0)  LAST_PERIOD 
	from 
	( 
		SELECT t1.FINPROD_ID , 
		( nvl(t1.DSC_COST_AMT,0)+nvl(t1.TDY_FLOAT_INGPL,0)+nvl(t1.TDY_INTINCEXP,0)+ nvl(t1.DELAY_PAY_AMT,0)) as TRADE_AMT,t2.MDATE 
		from PTL_SEC_VALUTION t1 
		INNER JOIN FIN_TRADE_PRODUCT t2 on t2.FINPROD_ID=t1.FINPROD_ID and t2.FINPROD_TYPE =''F02'' 
		where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE = date''${valDate}''-1 
	UNION ALL 
		select n.FINPROD_ID , 
		 nvl(sum(decode(n.PS,''T06'',n.TRADE_AMT)),0) 
		  -nvl(sum(decode(n.PS,''T08'',n.TRADE_AMT)),0)	 as  TRADE_AMT,t2.MDATE 
		  from TRD_PRODUCT_DEAL n 
		  INNER JOIN TRD_PRODUCT_DEAL_ADD n1 ON n1.trade_id =n.TRADE_ID 
		  INNER JOIN FIN_TRADE_PRODUCT t2 on t2.FINPROD_ID=n.FINPROD_ID and t2.FINPROD_TYPE =''F02'' 
		  where n1.PORTFOLIO_ID in ${portfolioCode} and  n.TRADE_DATE = date''${valDate}'' 
		  and n.PS in (''T06'',''T08'') group by n.FINPROD_ID,t2.MDATE 
	) A1 
)', 'portfolioCode', 'N', 'admin', '2222222', TIMESTAMP '2020-05-05 14:23:22', 'admin', TIMESTAMP '2020-05-05 14:23:22');
