from PTL_PORTFOLIO_VALUATION t1 
inner join jzDayData on 1=1 
where t1.PORTFOLIO_ID in ${portfolioCode} and t1.CDATE <= date ''${valDate}'' 
order by t1.CDATE 
) 
select 
max( 
round(allLjSylData1.ljSylValue - 
(select min(allLjSylData2.ljSylValue) from allLjSylData allLjSylData2 where allLjSylData2.CDATE <= allLjSylData1.CDATE), 6) 
) 
as resultValue 
from allLjSylData allLjSylData1', 'portfolioCode', 'N', 'whmcp', '2222222', TIMESTAMP '2020-05-05 14:23:23', 'whmcp', TIMESTAMP '2020-05-05 14:23:23');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('ZHGZJYE', '03', 'SQL', 'select m.PORTFOLIO_ID AS RKEY,nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)),0) as  RVALUE from PTL_SEC_VALUTION m	 
INNER JOIN FIN_TRADE_PRODUCT n on m.FINPROD_ID = n.FINPROD_ID and n.FINPROD_TYPE2 in (''F02'',''F04'')	 
where    m.CDATE =date''${valDate}''-1  group by m.PORTFOLIO_ID	 
	 
union all	 
   select t.PTL_BAG_ID as RKEY,	 
   ( select nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)),0) as  RVALUE from PTL_SEC_VALUTION m	 
	INNER JOIN FIN_TRADE_PRODUCT n on m.FINPROD_ID = n.FINPROD_ID and n.FINPROD_TYPE2 in (''F02'',''F04'') 
	where    m.CDATE =date''${valDate}''-1  AND  
	m.PORTFOLIO_ID in (   select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=t.PTL_BAG_ID) 
   )	 
   from RSK_PORTFOLIO_PACKAGE t', 'portfolioCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:23', 'jjpei', TIMESTAMP '2020-05-05 14:23:23');
