INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('SSGSKLTGB', '01', 'SQL', 'SELECT (SELECT nvl(sum(s.C_SHARES),0) FROM MST_SHARE_PRICE s WHERE s.SHARES_ID=t2.FINPROD_MARKET_ID AND s.DEAL_DATE=(		
		SELECT max(DEAL_DATE) FROM MST_SHARE_PRICE m WHERE m.SHARES_ID=t2.FINPROD_MARKET_ID and m.DEAL_DATE<=date''${valDate}'')
	) AS RVALUE,	
    T2.FINPROD_ID RKEY		
	from FIN_PRODUCT t2 	
	inner join FIN_PRODUCT_TYPE fpt on t2.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 and (fpt.TYPE_8 =''F11''  OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B17''))	
	GROUP BY T2.FINPROD_ID,T2.FINPROD_MARKET_ID', 'assetCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:28', 'jjpei', TIMESTAMP '2020-05-05 14:23:28');
