 GROUP BY t2.FINPROD_ID,t1.NETPRICE, t1.VALUE_DATE
)where rk=1', 'assetCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:31', 'jjpei', TIMESTAMP '2020-05-05 14:23:31');
