INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('DYGNFDBJYJE', '01', 'SQL', 'with temp as (select  m.FINPROD_ID, 
case when m.FINPROD_TYPE2 = ''F01'' then m.ISSUER else m.FINANCIER end org_code 
FROM  FIN_PRODUCT m
INNER JOIN  FIN_PRODUCT_TYPE fpt ON  m.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0
AND (  (fpt.TYPE_8 =''F06'' and fpt.TYPE_6 IN(''P01'',''P11'')) OR  ( fpt.TYPE_8 =''F01''  AND fpt.TYPE_6 =''B18'')))

select a.FINPROD_ID RKEY,CASE WHEN CORORG IS NULL THEN 0 ELSE 1 END RVALUE from  temp a
left join (SELECT ORG_NO,COUNT(COR_ORGID) AS CORORG FROM INF_ORG_CORRELATION WHERE ORG_NO <> COR_ORGID GROUP BY ORG_NO) b ON a.org_code=b.ORG_NO', 'assetCode', 'N', 'jjpei', '00000', TIMESTAMP '2020-05-05 14:23:31', 'jjpei', TIMESTAMP '2020-05-05 14:23:31');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('ZJCCSZ', '03', 'SQL', 'select m.PORTFOLIO_ID as RKEY,nvl(sum(nvl(TDY_FLOAT_INGPL, 0) + nvl(DSC_COST_AMT, 0)+ nvl(TDY_INTINCEXP, 0)),0) as RVALUE from PTL_SEC_VALUTION m	 
INNER JOIN FIN_PRODUCT_TYPE n on m.FINPROD_ID=n.FINPROD_ID and n.TYPE_8=''F01''  AND n.BRANCH=0 
where  m.CDATE =date''${valDate}''-1 group by m.PORTFOLIO_ID', 'portfolioCode', 'N', 'admin', '001', TIMESTAMP '2020-06-08 15:46:30', 'admin', TIMESTAMP '2020-06-08 15:46:30');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('DYGNFDBJYJE', '02', 'SQL', 'with temp as (select  m.FINPROD_ID, 
case when m.FINPROD_TYPE2 = ''F01'' then m.ISSUER else m.FINANCIER end org_code 
FROM  FIN_PRODUCT m
INNER JOIN  FIN_PRODUCT_TYPE fpt ON  m.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0
AND (  (fpt.TYPE_8 =''F06'' and fpt.TYPE_6 IN(''P01'',''P11'')) OR  ( fpt.TYPE_8 =''F01''  AND fpt.TYPE_6 =''B18'')))

select a.FINPROD_ID RKEY,CASE WHEN CORORG IS NULL THEN 0 ELSE 1 END RVALUE from  temp a
left join (SELECT ORG_NO,COUNT(COR_ORGID) AS CORORG FROM INF_ORG_CORRELATION WHERE ORG_NO <> COR_ORGID GROUP BY ORG_NO) b ON a.org_code=b.ORG_NO', 'assetCode', 'N', 'jjpei', '00000', TIMESTAMP '2020-05-05 14:23:32', 'jjpei', TIMESTAMP '2020-05-05 14:23:32');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('ZJCCSZ', '04', 'SQL', 'select nvl(sum(nvl(RVALUE, 0)),0) as RVALUE from	 
 (	select nvl(sum(nvl(TDY_FLOAT_INGPL, 0) + nvl(DSC_COST_AMT, 0)+ nvl(TDY_INTINCEXP, 0)),0) as RVALUE from PTL_SEC_VALUTION m 
	INNER  JOIN FIN_PRODUCT_TYPE n on m.FINPROD_ID=n.FINPROD_ID and n.TYPE_8=''F01'' AND n.BRANCH=0 
	where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}'' -1 
union ALL	 
	  select  
	  nvl(sum(decode(n.PS,''T01'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) 
  +nvl(sum(decode(n.PS,''T04'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 
  +nvl(sum(decode(n.PS,''T52'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 
  -nvl(sum(decode(n.PS,''T02'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 
  -nvl(sum(decode(n.PS,''T03'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 
  -nvl(sum(decode(n.PS,''T06'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) 
  -nvl(sum(decode(n.PS,''T08'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 
  -nvl(sum(decode(n.PS,''T09'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 
  -nvl(sum(decode(n.PS,''T11'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)
  -nvl(sum(decode(n.PS,''T22'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 
  -nvl(sum(decode(n.PS,''T23'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 
  -nvl(sum(decode(n.PS,''T39'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)  as TRADE_AMT	 
	  from  TRD_PRODUCT_DEAL n 
	  inner JOIN TRD_PRODUCT_DEAL_ADD n1 ON n.TRADE_ID =n1.TRADE_ID 
	   INNER  JOIN FIN_PRODUCT_TYPE  m on m.FINPROD_ID=n.FINPROD_ID and m.TYPE_8=''F01'' AND m.BRANCH=0 
	  where  n1.PORTFOLIO_ID in ${portfolioCode}  and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T01'',''T02'',''T03'',''T04'',''T06'',''T08'',''T09'',''T11'',''T22'',''T23'',''T52'',''T39'')  
union ALL 	 
  select 	 
   nvl(sum(decode(n.PS,''T01'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 
  +nvl(sum(decode(n.PS,''T04'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 
  +nvl(sum(decode(n.PS,''T52'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 
  -nvl(sum(decode(n.PS,''T02'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 
  -nvl(sum(decode(n.PS,''T03'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 
  -nvl(sum(decode(n.PS,''T06'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 
  -nvl(sum(decode(n.PS,''T08'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 
  -nvl(sum(decode(n.PS,''T09'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 
  -nvl(sum(decode(n.PS,''T11'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)
  -nvl(sum(decode(n.PS,''T22'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T23'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	
  -nvl(sum(decode(n.PS,''T39'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)  as TRADE_AMT	 
  from WFL_TRD_PRODUCT_DEAL_ADD m	 
  inner join WFL_TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID and n.TRADE_STATUS != ''03''	 
  INNER  JOIN FIN_PRODUCT_TYPE  m1 on m1.FINPROD_ID=n.FINPROD_ID and m1.TYPE_8=''F01'' AND m1.BRANCH=0	 
  where m.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' 	 
  and n.PS in (''T01'',''T02'',''T03'',''T04'',''T06'',''T08'',''T09'',''T11'',''T22'',''T23'',''T52'',''T39'')  	 
 ) s1', 'portfolioCode', 'N', 'admin', '001', TIMESTAMP '2020-06-08 15:46:30', 'admin', TIMESTAMP '2020-06-08 15:46:30');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('ZJCCSZ', '05', 'SQL', 'select  nvl(sum(nvl(TDY_FLOAT_INGPL, 0) + nvl(DSC_COST_AMT, 0)+ nvl(TDY_INTINCEXP, 0)),0) as RVALUE from PTL_SEC_VALUTION m	
