INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('DBJYSZJJ', '01', 'SQL', 'SELECT secid AS RKEY,netprice AS RVALUE
FROM
(SELECT t2.FINPROD_ID as secid,t1.NETPRICE as netprice,rank() over (partition by t2.FINPROD_ID order by t1.VALUE_DATE desc) rk
 FROM MST_BOND_VALUATION_INFO t1
 inner JOIN FIN_PRODUCT t2 ON t2.FINPROD_MARKET_ID=t1.SEC_ID
 WHERE t1.VALUE_DATE<=DATE''${valDate}''
 AND T1.VALUE_SOURCE =(CASE WHEN t2.TRADE_MARKET IN(''03'',''04'') THEN ''CSD'' ELSE ''CBC'' END)
 GROUP BY t2.FINPROD_ID,t1.NETPRICE, t1.VALUE_DATE
)where rk=1', 'assetCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:32', 'jjpei', TIMESTAMP '2020-05-05 14:23:32');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('DBJYSZJJ', '04', 'SQL', 'SELECT secid AS RKEY,netprice AS RVALUE
FROM
(SELECT t2.FINPROD_ID as secid,t1.NETPRICE as netprice,rank() over (partition by t2.FINPROD_ID order by t1.VALUE_DATE desc) rk
 FROM MST_BOND_VALUATION_INFO t1
 inner JOIN FIN_PRODUCT t2 ON t2.FINPROD_MARKET_ID=t1.SEC_ID
 WHERE t1.VALUE_DATE<=DATE''${valDate}''
 AND T1.VALUE_SOURCE =(CASE WHEN t2.TRADE_MARKET IN(''03'',''04'') THEN ''CSD'' ELSE ''CBC'' END)
 GROUP BY t2.FINPROD_ID,t1.NETPRICE, t1.VALUE_DATE
)where rk=1', 'assetCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:32', 'jjpei', TIMESTAMP '2020-05-05 14:23:32'); 
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('FHMB', '05', 'SQL', 'SELECT
	nvl(SUM(nvl(PTL_SEC_VALUTION.DSC_COST_AMT, 0)),0) AS CST,
	nvl(SUM(nvl(PTL_SEC_VALUTION.SHARE_AMT, 0)),0) AS QTY,
	nvl(SUM(nvl(PTL_SEC_VALUTION.TDY_FLOAT_INGPL, 0) + nvl(PTL_SEC_VALUTION.DSC_COST_AMT, 0)+nvl(PTL_SEC_VALUTION.TDY_INTINCEXP, 0)+nvl(PTL_SEC_VALUTION.DELAY_PAY_AMT, 0)),0) AS MKT,
	FIN_PRODUCT_TYPE.TYPE_4 windAssetType,
	FIN_PRODUCT_TYPE.TYPE_5 windAssetType2,
	FIN_PRODUCT_TYPE.TYPE_6 assetType,
	FIN_PRODUCT_TYPE.TYPE_7 assetType2,
	FIN_PRODUCT_ADD.INVEST_NATURE investNature,
	REP_ASSET_DEPT.REP_ASSET_TYPE deptType,
	REP_ASSET_DEPT.REP_ASSET_TYPE deptType2,
	PTL_SEC_VALUTION.FINPROD_ID finprodId,
	FIN_PRODUCT.ISSUER issuer,
	MST_CUSTOMER_INFO.INDUSTRY industry,
	MST_CUSTOMER_INFO.INDUSTRY2 industry2,
	ZXRATING.GRADE_RESULT bondGradeType,
	ZTRATING.GRADE_RESULT bodyGradeType, PTL_SEC_VALUTION.PORTFOLIO_ID PORTFOLIO_ID,
	FIN_PRODUCT.MDATE mdate
	FROM PTL_SEC_VALUTION
	LEFT JOIN FIN_PRODUCT ON PTL_SEC_VALUTION.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
	LEFT JOIN (SELECT s1.*,s2.INDUSTRY,s2.INDUSTRY2 FROM MST_CUSTOMER_INFO s1 INNER JOIN MST_CUSTOMER_INFO_ADD s2 ON s1.CUSTOMER_ID=s2.CUSTOMER_ID) MST_CUSTOMER_INFO ON FIN_PRODUCT.ISSUER = MST_CUSTOMER_INFO.CUSTOMER_ID
	LEFT JOIN FIN_PRODUCT_TYPE ON PTL_SEC_VALUTION.FINPROD_ID = FIN_PRODUCT_TYPE.FINPROD_ID
	LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT_ADD.FINPROD_ID = PTL_SEC_VALUTION.FINPROD_ID
	LEFT JOIN REP_ASSET_DEPT ON PTL_SEC_VALUTION.FINPROD_ID = REP_ASSET_DEPT.REP_FINPROD_ID
	LEFT JOIN (SELECT * FROM (SELECT O_CODE,GRADE_RESULT,ROW_NUMBER() OVER(PARTITION BY O_CODE ORDER BY CREATE_TIME desc) AS rn FROM MST_BOND_CREDIT_RATING T WHERE O_TYPE = ''02'' AND GRADE_DATE<=DATE ''${valDate}'') where rn=1 ) ZXRATING ON ZXRATING.O_CODE = PTL_SEC_VALUTION.FINPROD_ID
	LEFT JOIN (SELECT * FROM (SELECT O_CODE,GRADE_DATE,GRADE_RESULT,ROW_NUMBER() OVER(PARTITION BY O_CODE ORDER BY CREATE_TIME desc) AS rn FROM MST_BOND_CREDIT_RATING T WHERE O_TYPE = ''01'' AND GRADE_DATE<=DATE ''${valDate}'') where rn=1 ) ZTRATING ON ZTRATING.O_CODE = PTL_SEC_VALUTION.FINPROD_ID
	WHERE PTL_SEC_VALUTION.PORTFOLIO_ID IN ${portfolioCode} AND PTL_SEC_VALUTION.CDATE = DATE ''${valDate}''
	GROUP BY
	PTL_SEC_VALUTION.PORTFOLIO_ID,FIN_PRODUCT_TYPE.TYPE_4,FIN_PRODUCT_TYPE.TYPE_5,FIN_PRODUCT_TYPE.TYPE_6,FIN_PRODUCT_TYPE.TYPE_7,FIN_PRODUCT_ADD.INVEST_NATURE,REP_ASSET_DEPT.REP_ASSET_TYPE,
	PTL_SEC_VALUTION.FINPROD_ID,FIN_PRODUCT.ISSUER,MST_CUSTOMER_INFO.INDUSTRY,MST_CUSTOMER_INFO.INDUSTRY2,ZXRATING.GRADE_RESULT,ZTRATING.GRADE_RESULT,FIN_PRODUCT.MDATE', 'portfolioCode', 'N', 'admin', '001', TIMESTAMP '2020-05-05 14:23:32', 'admin', TIMESTAMP '2020-05-05 14:23:32');
 
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('XJGM', '02', 'SQL', '  select m.PORTFOLIO_ID RKEY,nvl(sum(n.AMOUNT),0) as  RVALUE  from PTL_PORTFOLIO m 	 
  LEFT JOIN PTL_CASH_POSITION n ON m.PORTFOLIO_ID=n.PORTFOLIO_ID AND  n.HODING_TYPE=''03'' AND n.CDATE =date''${valDate}''-1	 
  where  m.PORTFOLIO_TYPE IN (''01'',''02'') AND m.MDATE>date''${valDate}''  group by m.PORTFOLIO_ID	 
union all	 
   select t.PTL_BAG_ID as RKEY,	 
   ( select nvl(sum(AMOUNT),0) as  TRADE_AMT from PTL_CASH_POSITION	 
	where  HODING_TYPE=''03'' and CDATE =date''${valDate}''-1  AND  
	PORTFOLIO_ID in (select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=t.PTL_BAG_ID) 
   )	 
   from RSK_PORTFOLIO_PACKAGE t	', 'portfolioCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:32', 'jjpei', TIMESTAMP '2020-05-05 14:23:32');
