 	 where  PORTFOLIO_ID in ${portfolioCode} and HODING_TYPE=''03'' and CDATE =date''${valDate}''', 'portfolioCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:32', 'jjpei', TIMESTAMP '2020-05-05 14:23:32');
