INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('CPZDHC', '03', 'SQL', 'select 1 from dual', 'portfolioCode', 'N', 'whmcp', '2222222', TIMESTAMP '2020-05-05 14:23:33', 'whmcp', TIMESTAMP '2020-05-05 14:23:33');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('DYZCGM', '02', 'SQL', 'select
 sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)) as RVALUE, t1.PORTFOLIO_ID||'',''||t1.FINPROD_ID as RKEY
from PTL_SEC_VALUTION t1
 left join FIN_PRODUCT t2
  on t1.FINPROD_ID = t2.FINPROD_ID
left join (SELECT * FROM FIN_TRADE_PRODUCT WHERE BRANCH=0) t3
  on t1.FINPROD_ID = t3.FINPROD_ID
where  t1.CDATE = date''${valDate}''-1  AND t1.PORTFOLIO_ID!=t1.FINPROD_ID
and ((t3.FINPROD_TYPE2 is null and t2.FINPROD_TYPE2 is not null) or (t3.FINPROD_TYPE2 not in (''F02'', ''F04'', ''F08'',''F11'',''F12'',''F13'',''F14'',''F15'',''F25'') AND t3.BRANCH=0))
group by t1.PORTFOLIO_ID,t1.FINPROD_ID,t2.FINPROD_NAME

union all
  select sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)) as RVALUE, s2.PTL_BAG_ID||'',''||s1.FINPROD_ID as RKEY
 from (select t1.*
from PTL_SEC_VALUTION t1
 left join FIN_PRODUCT t2
  on t1.FINPROD_ID = t2.FINPROD_ID
left join (SELECT * FROM FIN_TRADE_PRODUCT WHERE BRANCH=0) t3
  on t1.FINPROD_ID = t3.FINPROD_ID
where  t1.CDATE = date''${valDate}''-1   AND t1.PORTFOLIO_ID!=t1.FINPROD_ID
and ((t3.FINPROD_TYPE2 is null and t2.FINPROD_TYPE2 is not null) or (t3.FINPROD_TYPE2 not in (''F02'',  ''F04'', ''F08'',''F11'',''F12'',''F13'',''F14'',''F15'',''F25'') AND t3.BRANCH=0))
) s1,( select t1.PORTFOLIO_ID,t1.PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'')
s2 where s1.PORTFOLIO_ID=s2.PORTFOLIO_ID  group by s2.PTL_BAG_ID,s1.FINPROD_ID', 'portfolioCode,assetCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-07 15:46:13', 'jjpei', TIMESTAMP '2020-05-07 15:46:13');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('MOTHERDZTDQTUZDWETE', '05', 'SQL', 'SELECT nvl(t2.ISSUE_AMT,0)*BOND.PRICE/100 AS RVALUE,	
T2.FINPROD_ID RKEY,t2.FINPROD_NAME RKEYCN FROM PTL_SEC_VALUTION T1	
INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F01''	
LEFT JOIN (	
    SELECT SEC_ID,nvl(PRICE,100) PRICE FROM (SELECT SEC_ID,PRICE, RANK() OVER(PARTITION BY SEC_ID ORDER BY VALUE_DATE DESC ) AS rowno	
	FROM MST_BOND_VALUATION_INFO WHERE VALUE_DATE<=date''${valDate}'') WHERE rowno=1
) BOND ON t2.FINPROD_MARKET_ID=BOND.SEC_ID	
WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND t1.CDATE=date''${valDate}''', 'assetCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:33', 'jjpei', TIMESTAMP '2020-05-05 14:23:33');
