left join FIN_PRODUCT_TYPE t2 on t1.FINPROD_ID=t2.FINPROD_ID	
where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE=date''${valDate}'' and t2.TYPE_8 =''F11''', 'portfolioCode', 'N', 'GY', '001', TIMESTAMP '2020-05-13 11:20:25', 'GY', TIMESTAMP '2020-05-13 11:20:25');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('FKFSCPGLDXZC', '03', 'SQL', 'SELECT Y1.PORTFOLIO_ID AS RKEY,SUM(TRADE_AMT)  AS RVALUE 					 
FROM(					 
		 SELECT	 T1.PORTFOLIO_ID,SUM(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)) AS TRADE_AMT		 
		 FROM PTL_SEC_VALUTION T1			 
	     LEFT JOIN FIN_PRODUCT T2 ON T1.FINPROD_ID=T2.FINPROD_ID 				 
	     LEFT JOIN MST_BOND_CREDIT_RATING T3 ON T3.O_CODE=T2.Finprod_Market_Id				 
	     WHERE  T1.CDATE = DATE''${valDate}''-1  AND T1.PORTFOLIO_ID!=T1.FINPROD_ID				 
	     AND T2.FINPROD_TYPE2  =''F01'' AND T2.ISSUE_TYPE =''01''				 
	     AND T3.GRADE_RESULT =''02''				 
	     GROUP BY T1.PORTFOLIO_ID				 
	 UNION ALL				 
		 SELECT M.PORTFOLIO_ID,NVL(SUM(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)),0) AS TRADE_AMT			 
		 FROM PTL_SEC_VALUTION M			 
	     INNER JOIN FIN_PRODUCT N ON M.FINPROD_ID =N.FINPROD_ID AND N.FINPROD_TYPE2 =''F01''				 
	     INNER JOIN FIN_PRODUCT_TYPE T3  ON N.FINPROD_ID =T3.FINPROD_ID  AND (T3.TYPE_4 IN (''B01'',''B02'',''B03'') OR (T3.TYPE_4 =''B05'' AND T3.TYPE_5=''01''))				 
	     WHERE M.CDATE =DATE''${valDate}''-1				 
	     AND M.PORTFOLIO_ID!=M.FINPROD_ID				 
	     GROUP BY M.PORTFOLIO_ID				 
) Y1 GROUP BY Y1.PORTFOLIO_ID', 'portfolioCode', 'N', 'GY', '001', TIMESTAMP '2020-05-13 11:14:28', 'GY', TIMESTAMP '2020-05-13 11:14:28');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('FKFSCPGLDXZC', '02', 'SQL', 'SELECT Y1.PORTFOLIO_ID AS RKEY,SUM(TRADE_AMT)  AS RVALUE 					 
FROM(					 
		 SELECT	 T1.PORTFOLIO_ID,SUM(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)) AS TRADE_AMT		 
		 FROM PTL_SEC_VALUTION T1			 
	     LEFT JOIN FIN_PRODUCT T2 ON T1.FINPROD_ID=T2.FINPROD_ID 				 
	     LEFT JOIN MST_BOND_CREDIT_RATING T3 ON T3.O_CODE=T2.Finprod_Market_Id				 
	     WHERE  T1.CDATE = DATE''${valDate}''-1  AND T1.PORTFOLIO_ID!=T1.FINPROD_ID				 
	     AND T2.FINPROD_TYPE2  =''F01'' AND T2.ISSUE_TYPE =''01''				 
	     AND T3.GRADE_RESULT =''02''				 
	     GROUP BY T1.PORTFOLIO_ID				 
	 UNION ALL				 
		 SELECT M.PORTFOLIO_ID,NVL(SUM(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)),0) AS TRADE_AMT			 
		 FROM PTL_SEC_VALUTION M			 
	     INNER JOIN FIN_PRODUCT N ON M.FINPROD_ID =N.FINPROD_ID AND N.FINPROD_TYPE2 =''F01''				 
	     INNER JOIN FIN_PRODUCT_TYPE T3  ON N.FINPROD_ID =T3.FINPROD_ID  AND (T3.TYPE_4 IN (''B01'',''B02'',''B03'') OR (T3.TYPE_4 =''B05'' AND T3.TYPE_5=''01''))				 
	     WHERE M.CDATE =DATE''${valDate}''-1				 
	     AND M.PORTFOLIO_ID!=M.FINPROD_ID				 
	     GROUP BY M.PORTFOLIO_ID				 
) Y1 GROUP BY Y1.PORTFOLIO_ID', 'portfolioCode', 'N', 'GY', '001', TIMESTAMP '2020-05-13 11:14:28', 'GY', TIMESTAMP '2020-05-13 11:14:28');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('FKFSCPGLDXZC', '01', 'SQL', 'SELECT Y1.PORTFOLIO_ID AS RKEY,SUM(TRADE_AMT)  AS RVALUE 					 
FROM(					 
		 SELECT	 T1.PORTFOLIO_ID,SUM(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)) AS TRADE_AMT		 
		 FROM PTL_SEC_VALUTION T1			 
	     LEFT JOIN FIN_PRODUCT T2 ON T1.FINPROD_ID=T2.FINPROD_ID 				 
	     LEFT JOIN MST_BOND_CREDIT_RATING T3 ON T3.O_CODE=T2.Finprod_Market_Id				 
	     WHERE  T1.CDATE = DATE''${valDate}''-1  AND T1.PORTFOLIO_ID!=T1.FINPROD_ID				 
	     AND T2.FINPROD_TYPE2  =''F01'' AND T2.ISSUE_TYPE =''01''				 
	     AND T3.GRADE_RESULT =''02''				 
	     GROUP BY T1.PORTFOLIO_ID				 
	 UNION ALL				 
		 SELECT M.PORTFOLIO_ID,NVL(SUM(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)),0) AS TRADE_AMT			 
		 FROM PTL_SEC_VALUTION M			 
	     INNER JOIN FIN_PRODUCT N ON M.FINPROD_ID =N.FINPROD_ID AND N.FINPROD_TYPE2 =''F01''				 
	     INNER JOIN FIN_PRODUCT_TYPE T3  ON N.FINPROD_ID =T3.FINPROD_ID  AND (T3.TYPE_4 IN (''B01'',''B02'',''B03'') OR (T3.TYPE_4 =''B05'' AND T3.TYPE_5=''01''))				 
	     WHERE M.CDATE =DATE''${valDate}''-1				 
	     AND M.PORTFOLIO_ID!=M.FINPROD_ID				 
	     GROUP BY M.PORTFOLIO_ID				 
) Y1 GROUP BY Y1.PORTFOLIO_ID', 'portfolioCode', 'N', 'GY', '001', TIMESTAMP '2020-05-13 11:14:28', 'GY', TIMESTAMP '2020-05-13 11:14:28');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('FKFSCPGLDXZC', '05', 'SQL', 'SELECT nvl(SUM(TRADE_AMT),0) RVALUE FROM ( SELECT	SUM(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)) AS TRADE_AMT	 			
  FROM PTL_SEC_VALUTION T1	 				
  INNER JOIN FIN_PRODUCT T2 ON T1.FINPROD_ID=T2.FINPROD_ID  AND T2.FINPROD_TYPE2  =''F01'' AND T2.ISSUE_TYPE =''01''		 			
  INNER JOIN MST_BOND_CREDIT_RATING T3 ON T3.O_CODE=T2.Finprod_Market_Id  AND T3.GRADE_RESULT =''02''					
  WHERE  T1.CDATE = DATE''${valDate}''  AND T1.PORTFOLIO_ID!=T1.FINPROD_ID  AND T1.PORTFOLIO_ID IN ${portfolioCode}					
UNION ALL					
  SELECT	SUM(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)) AS TRADE_AMT	 			
  FROM PTL_SEC_VALUTION T1	 				
  inner JOIN FIN_PRODUCT T2 ON T1.FINPROD_ID=T2.FINPROD_ID AND T2.FINPROD_TYPE2  =''F01''					
  inner JOIN FIN_PRODUCT_TYPE T4 ON T4.FINPROD_ID=T2.FINPROD_ID AND (T4.TYPE_4 IN (''B01'',''B02'',''B03'') OR (T4.TYPE_4 =''B05'' AND T4.TYPE_5=''01''))					
  WHERE  T1.CDATE = DATE''${valDate}''  AND T1.PORTFOLIO_ID!=T1.FINPROD_ID	 				
  AND T1.PORTFOLIO_ID IN ${portfolioCode}					
  )', 'portfolioCode', 'N', 'GY', '001', TIMESTAMP '2020-05-13 11:14:28', 'GY', TIMESTAMP '2020-05-13 11:14:28');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('FSMCPBDTZWSSQYGQ', '01', 'SQL', 'SELECT
