INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('GMCPSTZBZLZC', '02', 'SQL', 'select	 
 sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)) as RVALUE, t1.PORTFOLIO_ID as RKEY	 
from PTL_SEC_VALUTION t1	 
 left join FIN_PRODUCT_TYPE t2 on t1.FINPROD_ID=t2.FINPROD_ID	 
where  t1.CDATE = date''${valDate}''-1  AND t1.PORTFOLIO_ID!=t1.FINPROD_ID	 
AND (t2.TYPE_8  IN (''F01'',''F02'',''F05'') OR (t2.TYPE_8=''F06'' AND T2.TYPE_6=''P08'') OR (t2.TYPE_8 IN (''F07'',''F10'') AND t2.TYPE_7 =''04''))	 
group by t1.PORTFOLIO_ID	 
union all	 
  select sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)) as RVALUE, s2.PTL_BAG_ID as RKEY	 
 from (select t1.*	 
from PTL_SEC_VALUTION t1	 
left join FIN_PRODUCT_TYPE t2 on t1.FINPROD_ID=t2.FINPROD_ID	 
where  t1.CDATE = date''${valDate}''-1 	AND t1.PORTFOLIO_ID!=t1.FINPROD_ID 
and  (t2.TYPE_8  IN (''F01'',''F02'',''F05'') OR (t2.TYPE_8=''F06'' AND T2.TYPE_6=''P08'')  OR (t2.TYPE_8 IN (''F07'',''F10'') AND t2.TYPE_7 =''04''))	 
) s1,( select t1.PORTFOLIO_ID,t1.PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'')	 
s2 where s1.PORTFOLIO_ID=s2.PORTFOLIO_ID  group by s2.PTL_BAG_ID', 'portfolioCode', 'N', 'GY', '001', TIMESTAMP '2020-05-13 11:18:53', 'GY', TIMESTAMP '2020-05-13 11:18:53');
