INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('LLZDBJYJJ', '02', 'SQL', 'SELECT 0 RVALUE,FINPROD_ID RKEY FROM FIN_PRODUCT_TYPE  WHERE BRANCH=0 AND TYPE_8=''F01'' AND TYPE_6 IN（''B12'',''B01'',''B02'',''B03''） or (TYPE_6=''B05'' AND TYPE_7=''01'')', 'assetCode', 'N', 'GY', '001', TIMESTAMP '2020-05-18 09:10:11', 'GY', TIMESTAMP '2020-05-18 09:10:12');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('LLZDBJYJJ', '03', 'SQL', 'SELECT 0 RVALUE,FINPROD_ID RKEY FROM FIN_PRODUCT_TYPE  WHERE BRANCH=0 AND TYPE_8=''F01'' AND TYPE_6 IN（''B12'',''B01'',''B02'',''B03''） or (TYPE_6=''B05'' AND TYPE_7=''01'')', 'assetCode', 'N', 'GY', '001', TIMESTAMP '2020-05-18 09:10:11', 'GY', TIMESTAMP '2020-05-18 09:10:12');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('LLZDBJYJJ', '01', 'SQL', 'SELECT 0 RVALUE,FINPROD_ID RKEY FROM FIN_PRODUCT_TYPE  WHERE BRANCH=0 AND TYPE_8=''F01'' AND TYPE_6 IN（''B12'',''B01'',''B02'',''B03''） or (TYPE_6=''B05'' AND TYPE_7=''01'')', 'assetCode', 'N', 'GY', '001', TIMESTAMP '2020-05-18 09:10:11', 'GY', TIMESTAMP '2020-05-18 09:10:12');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('ZHKTZZCXZ', '02', 'SQL', 'select VALUE AS RVALUE,TYPENAME AS RKEY from (with tmp as (select 												 
case when ${assetType}=''F01'' then ''PINAN_ASSET_TYPE,WINDTYPEONE,WINDTYPETWO''												 
when  ${assetType}=''F02'' then ''PINAN_ASSET_TYPE,FUND_ASSET_TYPE,FUND_ASSET_SECOND_TYPE''												  
when  ${assetType}=''F06'' then ''PINAN_ASSET_TYPE,ASSET_TYPE_PROJECT,ASSET_TYPE_PROJECT_TWO''												 
when  ${assetType}=''F05'' then ''PINAN_ASSET_TYPE,DEPO_ASSET_TYPE,DEPO_TYPE''												 
else ''PINAN_ASSET_TYPE'' end ITEMCODE												 
from dual)												 
SELECT m.VALUE,n.ITEM_VALUE as TYPENAME FROM (												 
SELECT CASE	WHEN											 
		${assetCode}= ''null'' THEN										 
			${assetType} ELSE 									 
			            (									 
							SELECT					 
							CASE WHEN assetType IS NULL 					 
							THEN ${assetType} ELSE assetType 					 
							END as assetType					 
							FROM					 
							(					 
								SELECT				 
								CASE WHEN TYPE_8 IN(''F01'',''F02'',''F06'') THEN TYPE_8||''_''||TYPE_6				 
								     WHEN TYPE_8 =''F05'' THEN (				 
								     CASE WHEN TYPE_7 IS NOT NULL THEN TYPE_8||''_''||TYPE_7				 
								     ELSE TYPE_8||''_''||TYPE_6 END )				 
									 END AS assetType 			 
								FROM				 
									FIN_PRODUCT_TYPE t 			 
								WHERE				 
								t.FINPROD_ID=${assetCode} and  t.BRANCH = ''0'' 				 
							) t 					 
						) end as VALUE						 
				FROM dual								 
				) m left join (								 
				select DICT_CODE,''F01_''||ITEM_CODE AS ITEM_CODE,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''WINDTYPEONE''								 
				union all								 
				select DICT_CODE,''F02_''||ITEM_CODE ,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''FUND_ASSET_TYPE''								 
				union all								 
				select DICT_CODE,''F05_''||ITEM_CODE ,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''DEPO_TYPE''								 
				union all								 
				select DICT_CODE,''F05_''||ITEM_CODE ,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''DEPO_ASSET_TYPE''								 
				union all								 
				select DICT_CODE,''F06_''||ITEM_CODE ,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''ASSET_TYPE_PROJECT''								 
				UNION ALL 								 
				SELECT DICT_CODE,ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST WHERE DICT_CODE  IN (''PINAN_ASSET_TYPE'',''WINDTYPETWO'',''FUND_ASSET_SECOND_TYPE'',''ASSET_TYPE_PROJECT_TWO'')								 
				) n on m.VALUE=n.ITEM_CODE and n.DICT_CODE in 								 
(select REGEXP_SUBSTR (ITEMCODE, ''[^,]+'', 1,rownum) from tmp connect by rownum<=LENGTH (ITEMCODE) - LENGTH (regexp_replace(ITEMCODE, '','', ''''))+1) WHERE m.VALUE IS NOT NULL)', 'portfolioCode', 'N', 'admin', '001', TIMESTAMP '2020-05-19 15:38:45', 'admin', TIMESTAMP '2020-05-19 15:38:46');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('ZHKTZZCXZ', '03', 'SQL', 'select VALUE AS RVALUE,TYPENAME AS RKEY from (with tmp as (select 												 
case when ${assetType}=''F01'' then ''PINAN_ASSET_TYPE,WINDTYPEONE,WINDTYPETWO''												 
when  ${assetType}=''F02'' then ''PINAN_ASSET_TYPE,FUND_ASSET_TYPE,FUND_ASSET_SECOND_TYPE''												  
when  ${assetType}=''F06'' then ''PINAN_ASSET_TYPE,ASSET_TYPE_PROJECT,ASSET_TYPE_PROJECT_TWO''												 
when  ${assetType}=''F05'' then ''PINAN_ASSET_TYPE,DEPO_ASSET_TYPE,DEPO_TYPE''												 
else ''PINAN_ASSET_TYPE'' end ITEMCODE												 
from dual)												 
SELECT m.VALUE,n.ITEM_VALUE as TYPENAME FROM (												 
SELECT CASE	WHEN											 
		${assetCode}= ''null'' THEN										 
			${assetType} ELSE 									 
			            (									 
							SELECT					 
							CASE WHEN assetType IS NULL 					 
							THEN ${assetType} ELSE assetType 					 
							END as assetType					 
							FROM					 
							(					 
								SELECT				 
								CASE WHEN TYPE_8 IN(''F01'',''F02'',''F06'') THEN TYPE_8||''_''||TYPE_6				 
								     WHEN TYPE_8 =''F05'' THEN (				 
								     CASE WHEN TYPE_7 IS NOT NULL THEN TYPE_8||''_''||TYPE_7				 
								     ELSE TYPE_8||''_''||TYPE_6 END )				 
									 END AS assetType 			 
								FROM				 
									FIN_PRODUCT_TYPE t 			 
								WHERE				 
								t.FINPROD_ID=${assetCode} and  t.BRANCH = ''0'' 				 
							) t 					 
						) end as VALUE						 
				FROM dual								 
				) m left join (								 
				select DICT_CODE,''F01_''||ITEM_CODE AS ITEM_CODE,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''WINDTYPEONE''								 
				union all								 
				select DICT_CODE,''F02_''||ITEM_CODE ,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''FUND_ASSET_TYPE''								 
				union all								 
				select DICT_CODE,''F05_''||ITEM_CODE ,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''DEPO_TYPE''								 
				union all								 
				select DICT_CODE,''F05_''||ITEM_CODE ,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''DEPO_ASSET_TYPE''								 
				union all								 
				select DICT_CODE,''F06_''||ITEM_CODE ,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''ASSET_TYPE_PROJECT''								 
				UNION ALL 								 
				SELECT DICT_CODE,ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST WHERE DICT_CODE  IN (''PINAN_ASSET_TYPE'',''WINDTYPETWO'',''FUND_ASSET_SECOND_TYPE'',''ASSET_TYPE_PROJECT_TWO'')								 
				) n on m.VALUE=n.ITEM_CODE and n.DICT_CODE in 								 
(select REGEXP_SUBSTR (ITEMCODE, ''[^,]+'', 1,rownum) from tmp connect by rownum<=LENGTH (ITEMCODE) - LENGTH (regexp_replace(ITEMCODE, '','', ''''))+1) WHERE m.VALUE IS NOT NULL)', 'portfolioCode', 'N', 'admin', '001', TIMESTAMP '2020-05-19 15:38:45', 'admin', TIMESTAMP '2020-05-19 15:38:46');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('ZHKTZZCXZ', '01', 'SQL', 'select VALUE AS RVALUE,TYPENAME AS RKEY from (with tmp as (select 												 
case when ${assetType}=''F01'' then ''PINAN_ASSET_TYPE,WINDTYPEONE,WINDTYPETWO''												 
when  ${assetType}=''F02'' then ''PINAN_ASSET_TYPE,FUND_ASSET_TYPE,FUND_ASSET_SECOND_TYPE''												  
when  ${assetType}=''F06'' then ''PINAN_ASSET_TYPE,ASSET_TYPE_PROJECT,ASSET_TYPE_PROJECT_TWO''												 
when  ${assetType}=''F05'' then ''PINAN_ASSET_TYPE,DEPO_ASSET_TYPE,DEPO_TYPE''												 
else ''PINAN_ASSET_TYPE'' end ITEMCODE												 
from dual)												 
SELECT m.VALUE,n.ITEM_VALUE as TYPENAME FROM (												 
SELECT CASE	WHEN											 
		${assetCode}= ''null'' THEN										 
			${assetType} ELSE 									 
			            (									 
							SELECT					 
							CASE WHEN assetType IS NULL 					 
							THEN ${assetType} ELSE assetType 					 
							END as assetType					 
							FROM					 
							(					 
								SELECT				 
								CASE WHEN TYPE_8 IN(''F01'',''F02'',''F06'') THEN TYPE_8||''_''||TYPE_6				 
								     WHEN TYPE_8 =''F05'' THEN (				 
								     CASE WHEN TYPE_7 IS NOT NULL THEN TYPE_8||''_''||TYPE_7				 
								     ELSE TYPE_8||''_''||TYPE_6 END )				 
									 END AS assetType 			 
								FROM				 
									FIN_PRODUCT_TYPE t 			 
								WHERE				 
								t.FINPROD_ID=${assetCode} and  t.BRANCH = ''0'' 				 
							) t 					 
						) end as VALUE						 
				FROM dual								 
				) m left join (								 
				select DICT_CODE,''F01_''||ITEM_CODE AS ITEM_CODE,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''WINDTYPEONE''								 
				union all								 
				select DICT_CODE,''F02_''||ITEM_CODE ,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''FUND_ASSET_TYPE''								 
				union all								 
				select DICT_CODE,''F05_''||ITEM_CODE ,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''DEPO_TYPE''								 
				union all								 
				select DICT_CODE,''F05_''||ITEM_CODE ,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''DEPO_ASSET_TYPE''								 
				union all								 
				select DICT_CODE,''F06_''||ITEM_CODE ,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''ASSET_TYPE_PROJECT''								 
				UNION ALL 								 
				SELECT DICT_CODE,ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST WHERE DICT_CODE  IN (''PINAN_ASSET_TYPE'',''WINDTYPETWO'',''FUND_ASSET_SECOND_TYPE'',''ASSET_TYPE_PROJECT_TWO'')								 
				) n on m.VALUE=n.ITEM_CODE and n.DICT_CODE in 								 
(select REGEXP_SUBSTR (ITEMCODE, ''[^,]+'', 1,rownum) from tmp connect by rownum<=LENGTH (ITEMCODE) - LENGTH (regexp_replace(ITEMCODE, '','', ''''))+1) WHERE m.VALUE IS NOT NULL)', 'portfolioCode', 'N', 'admin', '001', TIMESTAMP '2020-05-19 15:38:45', 'admin', TIMESTAMP '2020-05-19 15:38:46');
 
 
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('CPFBQ', '04', 'SQL', 'SELECT
    case when REP_OPEN_CIRCLE = ''06'' then 0.5
     when REP_OPEN_CIRCLE = ''07'' then 1
     when REP_OPEN_CIRCLE = ''99'' 
     and round(REP_OPEN_CIRCLE_DAYS/365, 2) >= 0.5 then round(REP_OPEN_CIRCLE_DAYS/365, 2)
     else 0
    end as RVALUE
FROM
    REP_PROD_ISSUE
WHERE
        REP_FINPROD_ID = (select max(FINPROD_ID) from FIN_PRODUCT_ADD where PORTFOLIO_ID in ${portfolioCode})
    and REP_OPEN_CIRCLE in (''06'', ''07'', ''99'')
union all 
SELECT
   case when TERM_DAYS >= 0 then round(TERM_DAYS/365, 2) end as RVALUE
FROM
    FIN_PRODUCT
WHERE
        FINPROD_ID = (select max(FINPROD_ID) from FIN_PRODUCT_ADD where PORTFOLIO_ID in ${portfolioCode})
    and OPERATION_TYPE = ''01''', 'portfolioCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-06 11:26:27', 'jjpei', TIMESTAMP '2020-05-06 11:26:27');
