  where  m.PORTFOLIO_ID in ${portfolioCode}  and n.TRADE_DATE=date''${valDate}''', 'assetCode', 'N', 'lw03', '9901', TIMESTAMP '2020-05-15 12:49:57', 'lw03', TIMESTAMP '2020-05-15 12:49:57');
  
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('CPJZCJZ', '03', 'SQL', 'WITH  temp  as(			 
  SELECT 			 
       DISTINCT t2.PORTFOLIO_ID ,			 
       mujiData.mujiAmt  as AMOUNT			 
       from  PTL_PORTFOLIO t2			 
       left join 			 
       (			 
       select t1.PORTFOLIO_ID, sum(t1.TRADE_AMT) as mujiAmt from TRD_FIN_PRODUCT_DEAL_TOTAL t1			 
       WHERE  t1.PS in (''C1'', ''C2'')	 and t1.SETTLE_DATE <= date''${valDate}'' and t1.TRADE_STATUS=''01''		 
       group by t1.PORTFOLIO_ID			 
       ) mujiData			 
       on t2.PORTFOLIO_ID = mujiData.PORTFOLIO_ID			 
       where  t2.VDATE=date''${valDate}''			 
 UNION ALL			 
      SELECT 			 
       DISTINCT t1.PORTFOLIO_ID RKEY,			 
        nvl(TDY_ASSET_NETVALUE,0) as RVALUE			 
       from PTL_PORTFOLIO_VALUATION t1			 
       where  t1.CDATE=date''${valDate}''-1 			 
 )			 
 SELECT PORTFOLIO_ID RKEY,AMOUNT RVALUE FROM temp			 
union all			 
   select m.PTL_BAG_ID as RKEY,		 	 
   (		 	 
        SELECT sum(AMOUNT) FROM ( 			 
          SELECT PORTFOLIO_ID,AMOUNT FROM temp			 
	   	 ) t1 where t1.PORTFOLIO_ID in (select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1	  
	     inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=m.PTL_BAG_ID)		 
   ) AS RVALUE		 	 
   from RSK_PORTFOLIO_PACKAGE m', 'portfolioCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:31', 'jjpei', TIMESTAMP '2020-05-05 14:23:31');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('CPZZC', '02', 'SQL', 'WITH  temp  as(			 
  SELECT 			 
       DISTINCT t2.PORTFOLIO_ID ,			 
       mujiData.mujiAmt  as AMOUNT			 
       from  PTL_PORTFOLIO t2			 
       left join 			 
       (			 
       select t1.PORTFOLIO_ID, sum(t1.TRADE_AMT) as mujiAmt from TRD_FIN_PRODUCT_DEAL_TOTAL t1			 
       WHERE			 
           t1.PS in (''C1'', ''C2'')			 
           and t1.SETTLE_DATE <= date''${valDate}''	and t1.TRADE_STATUS=''01''		 
       group by t1.PORTFOLIO_ID			 
       ) mujiData			 
       on t2.PORTFOLIO_ID = mujiData.PORTFOLIO_ID			 
       where  t2.VDATE=date''${valDate}''			 
 UNION ALL			 
      SELECT 			 
       DISTINCT t1.PORTFOLIO_ID RKEY,			 
        nvl(TDY_ASSET_VALUE,0) as RVALUE			 
       from PTL_PORTFOLIO_VALUATION t1			 
       where  t1.CDATE=date''${valDate}''-1 			 
 )			 
   SELECT PORTFOLIO_ID RKEY,AMOUNT RVALUE FROM temp			 
union all			 
    select m.PTL_BAG_ID as RKEY,		 	 
   (		 	 
        SELECT sum(AMOUNT) FROM ( 			 
         SELECT PORTFOLIO_ID,AMOUNT FROM temp			 
	   	 ) t1 where t1.PORTFOLIO_ID in (select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1	  
	     inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=m.PTL_BAG_ID)		 
   ) AS RVALUE		 	 
   from RSK_PORTFOLIO_PACKAGE m', 'portfolioCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:30', 'jjpei', TIMESTAMP '2020-05-05 14:23:30');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('MOTHERDZTDQTUZDWETE', '04', 'SQL', 'WITH BOND AS (		 
  SELECT SEC_ID,nvl(PRICE,100) PRICE FROM (SELECT SEC_ID,PRICE, RANK() OVER(PARTITION BY SEC_ID ORDER BY VALUE_DATE DESC ) AS rowno		 
		FROM MST_BOND_VALUATION_INFO WHERE VALUE_DATE<=date''${valDate}'') WHERE rowno=1 
)		 
SELECT DISTINCT RVALUE,RKEY,RKEYCN FROM (		 
	SELECT nvl(t2.ISSUE_AMT,0)*BOND.PRICE/100 AS RVALUE,	 
	T2.FINPROD_ID RKEY,t2.FINPROD_NAME RKEYCN FROM PTL_SEC_VALUTION T1	 
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F01''	 
	LEFT JOIN BOND ON t2.FINPROD_MARKET_ID=BOND.SEC_ID	 
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND t1.CDATE=date''${valDate}''-1	 
UNION ALL		 
	SELECT nvl(t2.ISSUE_AMT,0)*BOND.PRICE/100 AS RVALUE,	 
    T2.FINPROD_ID RKEY,		 
	t2.FINPROD_NAME RKEYCN FROM TRD_PRODUCT_DEAL t1	 
	INNER JOIN TRD_PRODUCT_DEAL_ADD n1 ON t1.TRADE_ID =n1.TRADE_ID	 
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F01''	 
	LEFT JOIN BOND ON t2.FINPROD_MARKET_ID=BOND.SEC_ID	 
	WHERE n1.PORTFOLIO_ID IN ${portfolioCode} AND t1.TRADE_DATE=date''${valDate}''	 
UNION ALL		 
	SELECT nvl(t2.ISSUE_AMT,0)*BOND.PRICE/100 AS RVALUE,	 
    T2.FINPROD_ID RKEY,		 
	t2.FINPROD_NAME RKEYCN FROM WFL_TRD_PRODUCT_DEAL_ADD t1	 
	inner join WFL_TRD_PRODUCT_DEAL n on t1.TRADE_ID=n.TRADE_ID and n.TRADE_STATUS != ''03''	 
	INNER JOIN FIN_PRODUCT t2 ON n.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F01''	 
	LEFT JOIN BOND ON t2.FINPROD_MARKET_ID=BOND.SEC_ID	 
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND n.TRADE_DATE=date''${valDate}''	 
) S1', 'assetCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:32', 'jjpei', TIMESTAMP '2020-05-05 14:23:32');
