  INNER JOIN FIN_PRODUCT_TYPE s ON s.FINPROD_ID=n.FINPROD_ID AND s.BRANCH=0 AND (s.TYPE_6 IN (''B12'',''B01'',''B02'',''B03'') OR (s.TYPE_6=''B05'' AND s.TYPE_7=''01'')) 
  where  m.PORTFOLIO_ID in ${portfolioCode}  and n.TRADE_DATE=date''${valDate}''', 'assetCode', 'N', 'GY', '001', TIMESTAMP '2020-05-18 09:10:11', 'GY', TIMESTAMP '2020-05-18 09:10:12');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('LLZDBJYJJ', '05', 'SQL', 'SELECT DISTINCT n.UNIT_CPRICE as RVALUE ,n.FINPROD_ID RKEY 
  from TRD_PRODUCT_DEAL_ADD m 
  inner join TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID and n.FINPROD_TYPE2 =''F01'' AND n.PS IN (''T01'',''T02'',''T03'') 
  INNER JOIN FIN_PRODUCT_TYPE s ON s.FINPROD_ID=n.FINPROD_ID AND s.BRANCH=0 AND s.TYPE_6 IN（''B12'',''B01'',''B02'',''B03''） or (s.TYPE_6=''B05'' AND s.TYPE_7=''01'')
  where  m.PORTFOLIO_ID in ${portfolioCode}  and n.TRADE_DATE=date''${valDate}'' 
  UNION all 
  select DISTINCT n.UNIT_CPRICE as RVALUE ,n.FINPROD_ID RKEY 
  from WFL_TRD_PRODUCT_DEAL_ADD m 
  inner join WFL_TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID and n.FINPROD_TYPE2 =''F01'' AND n.PS IN (''T01'',''T02'',''T03'') and n.TRADE_STATUS != ''03'' 
  INNER JOIN FIN_PRODUCT_TYPE s ON s.FINPROD_ID=n.FINPROD_ID AND s.BRANCH=0 AND s.TYPE_6 IN（''B12'',''B01'',''B02'',''B03''） or (s.TYPE_6=''B05'' AND s.TYPE_7=''01'')
  where  m.PORTFOLIO_ID in ${portfolioCode}  and n.TRADE_DATE=date''${valDate}''', 'assetCode', 'N', 'GY', '001', TIMESTAMP '2020-05-18 09:10:11', 'GY', TIMESTAMP '2020-05-18 09:10:12');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('FBZHZQLZCZZR', '01', 'SQL', 'SELECT to_char(mdate,''yyyy-MM-dd'') AS RVALUE,
m.FINPROD_ID RKEY FROM  FIN_PRODUCT m
inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID and ((fpt.TYPE_8 =''F06'' and fpt.TYPE_6 IN(''P01'',''P11'')) OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B18''))', 'assetCode', 'N', 'jjpei', '99999', TIMESTAMP '2020-05-20 10:11:04', 'jjpei', TIMESTAMP '2020-05-20 10:11:04');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('FBZHZQLZCZZR', '02', 'SQL', 'SELECT to_char(mdate,''yyyy-MM-dd'') AS RVALUE,
m.FINPROD_ID RKEY FROM  FIN_PRODUCT m
inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID and ((fpt.TYPE_8 =''F06'' and fpt.TYPE_6 IN(''P01'',''P11'')) OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B18''))', 'assetCode', 'N', 'jjpei', '99999', TIMESTAMP '2020-05-20 10:11:04', 'jjpei', TIMESTAMP '2020-05-20 10:11:04');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('FBZHZQLZCZZR', '03', 'SQL', 'SELECT to_char(mdate,''yyyy-MM-dd'') AS RVALUE,
m.FINPROD_ID RKEY FROM  FIN_PRODUCT m
inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID and ((fpt.TYPE_8 =''F06'' and fpt.TYPE_6 IN(''P01'',''P11'')) OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B18''))', 'assetCode', 'N', 'jjpei', '99999', TIMESTAMP '2020-05-20 10:11:04', 'jjpei', TIMESTAMP '2020-05-20 10:11:04');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('GMZDDDZZQHJJ', '02', 'SQL', 'SELECT nvl(sum(nvl(RVALUE, 0)),0) as RVALUE,s1.RKEY  FROM (	 
	select 
	sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)) as RVALUE, t1.PORTFOLIO_ID||'',''||t1.FINPROD_ID as RKEY 
	from PTL_SEC_VALUTION t1 
	inner join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID and t2.FINPROD_TYPE2  IN (''F01'',''F06'',''F10'') 
	where  t1.CDATE = date''${valDate}''-1 
	group by t1.PORTFOLIO_ID,t1.FINPROD_ID,t2.FINPROD_NAME 
	UNION ALL 
	select sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)) as RVALUE, s2.PTL_BAG_ID||'',''||s1.FINPROD_ID as RKEY 
	from (select t1.* 
	from PTL_SEC_VALUTION t1 
	inner join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID and t2.FINPROD_TYPE2  IN (''F01'',''F06'',''F10'') 
	where  t1.CDATE = date''${valDate}''-1 
	) s1,( select t1.PORTFOLIO_ID,t1.PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' ) 
	s2 where s1.PORTFOLIO_ID=s2.PORTFOLIO_ID  group by s2.PTL_BAG_ID,s1.FINPROD_ID 
	) s1 group by s1.RKEY', 'portfolioCode,assetCode', 'N', 'GY', '001', TIMESTAMP '2020-05-13 11:07:39', 'GY', TIMESTAMP '2020-05-13 11:07:39');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('GMZDDDZZQHJJ', '03', 'SQL', 'SELECT nvl(sum(nvl(RVALUE, 0)),0) as RVALUE,s1.RKEY  FROM (	 
