INNER JOIN FIN_PRODUCT_ADD PFP	 
on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''02''	 
where  m.CDATE =date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID group by m.PORTFOLIO_ID', 'portfolioCode', 'N', 'GY', '001', TIMESTAMP '2020-05-13 11:04:54', 'GY', TIMESTAMP '2020-05-13 11:04:54');
