on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''02''	 
where  m.CDATE =date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID group by m.PORTFOLIO_ID', 'portfolioCode', 'N', 'GY', '001', TIMESTAMP '2020-05-13 11:04:54', 'GY', TIMESTAMP '2020-05-13 11:04:54');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('QYLZCGM', '05', 'SQL', 'select nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)),0) as  TRADE_AMT from PTL_SEC_VALUTION m	
INNER JOIN FIN_PRODUCT_ADD PFP	
on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''02''	
where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}'' AND m.PORTFOLIO_ID!=m.FINPROD_ID', 'portfolioCode', 'N', 'GY', '001', TIMESTAMP '2020-05-13 11:04:54', 'GY', TIMESTAMP '2020-05-13 11:04:54');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('FBZHZQLZCZZR', '04', 'SQL', 'select ceil(n.mdate-date''${valDate}'') as RVALUE,m.FINPROD_ID as RKEY,n.FINPROD_NAME AS RKEYCN   from PTL_SEC_VALUTION m
  INNER JOIN FIN_PRODUCT n on m.FINPROD_ID=n.FINPROD_ID and n.FINPROD_TYPE2 IN (''F18'',''F01'')
  inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID and ((fpt.TYPE_8 =''F06'' and fpt.TYPE_6 IN(''P01'',''P11'')) OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B18''))
  where  m.PORTFOLIO_ID in ${portfolioCode} and m.CDATE = date''${valDate}''', 'assetCode', 'N', 'jjpei', '99999', TIMESTAMP '2020-05-20 10:11:04', 'jjpei', TIMESTAMP '2020-05-20 10:11:04');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('FBZHZQLZCZZR', '05', 'SQL', 'select ceil(n.mdate-date''${valDate}'') as RVALUE,m.FINPROD_ID as RKEY,n.FINPROD_NAME AS RKEYCN   from PTL_SEC_VALUTION m
  INNER JOIN FIN_PRODUCT n on m.FINPROD_ID=n.FINPROD_ID and n.FINPROD_TYPE2 IN (''F18'',''F01'')
  inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID and ((fpt.TYPE_8 =''F06'' and fpt.TYPE_6 IN(''P01'',''P11'')) OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B18''))
  where  m.PORTFOLIO_ID in ${portfolioCode} and m.CDATE = date''${valDate}''', 'assetCode', 'N', 'jjpei', '99999', TIMESTAMP '2020-05-20 10:11:04', 'jjpei', TIMESTAMP '2020-05-20 10:11:04');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('TZDYSSGSFXGP', '02', 'SQL', 'SELECT nvl(sum(nvl(RVALUE, 0)),0) as RVALUE,s1.RKEY  FROM (	 
select	 
 sum(nvl(SHARE_AMT,0)) as RVALUE, t1.PORTFOLIO_ID||'',''||t1.FINPROD_ID as RKEY	 
from PTL_SEC_VALUTION t1	 
inner join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID 	 
inner join FIN_PRODUCT_TYPE fpt on t1.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 and (fpt.TYPE_8 =''F11''  OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B17''))	 
where  t1.CDATE = date''${valDate}''-1	 
group by t1.PORTFOLIO_ID,t1.FINPROD_ID,t2.FINPROD_NAME	 
UNION ALL	 
  select sum(nvl(SHARE_AMT,0)) as RVALUE, s2.PTL_BAG_ID||'',''||s1.FINPROD_ID as RKEY	 
 from (select t1.*	 
from PTL_SEC_VALUTION t1	 
inner join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID 	 
inner join FIN_PRODUCT_TYPE fpt on t1.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 and (fpt.TYPE_8 =''F11''  OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B17''))	 
where  t1.CDATE = date''${valDate}''-1	 
) s1,( select t1.PORTFOLIO_ID,t1.PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}''-1 )	 
s2 where s1.PORTFOLIO_ID=s2.PORTFOLIO_ID  group by s2.PTL_BAG_ID,s1.FINPROD_ID	 
 ) s1 group by s1.RKEY', 'portfolioCode,assetCode', 'N', 'GY', '001', TIMESTAMP '2020-05-13 11:08:24', 'GY', TIMESTAMP '2020-05-13 11:08:24');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('TZDYSSGSFXGP', '03', 'SQL', 'SELECT nvl(sum(nvl(RVALUE, 0)),0) as RVALUE,s1.RKEY  FROM (	 
select	 
 sum(nvl(SHARE_AMT,0)) as RVALUE, t1.PORTFOLIO_ID||'',''||t1.FINPROD_ID as RKEY	 
from PTL_SEC_VALUTION t1	 
inner join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID 	 
inner join FIN_PRODUCT_TYPE fpt on t1.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 and (fpt.TYPE_8 =''F11''  OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B17''))	 
where  t1.CDATE = date''${valDate}''-1	 
group by t1.PORTFOLIO_ID,t1.FINPROD_ID,t2.FINPROD_NAME	 
UNION ALL	 
  select sum(nvl(SHARE_AMT,0)) as RVALUE, s2.PTL_BAG_ID||'',''||s1.FINPROD_ID as RKEY	 
 from (select t1.*	 
from PTL_SEC_VALUTION t1	 
inner join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID 	 
inner join FIN_PRODUCT_TYPE fpt on t1.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 and (fpt.TYPE_8 =''F11''  OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B17''))	 
where  t1.CDATE = date''${valDate}''-1	 
) s1,( select t1.PORTFOLIO_ID,t1.PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}''-1 )	 
s2 where s1.PORTFOLIO_ID=s2.PORTFOLIO_ID  group by s2.PTL_BAG_ID,s1.FINPROD_ID	 
 ) s1 group by s1.RKEY', 'portfolioCode,assetCode', 'N', 'GY', '001', TIMESTAMP '2020-05-13 11:08:24', 'GY', TIMESTAMP '2020-05-13 11:08:24');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('FBSLCCPDQRHKFSLCCP', '01', 'SQL', 'select n.PORTFOLIO_ID RKEY,MDATE as RVALUE from PTL_PORTFOLIO m INNER JOIN PA_PTL_PORTFOLIO n 
  ON m.PORTFOLIO_ID=n.PORTFOLIO_ID AND n.OPEN_TYPE=''01'' 
  UNION ALL
  select n.PORTFOLIO_ID RKEY,MDATE as RVALUE from PTL_PORTFOLIO m 
  INNER JOIN PA_PTL_PORTFOLIO n ON m.PORTFOLIO_ID=n.PORTFOLIO_ID AND n.OPEN_TYPE=''02''
  INNER JOIN FIN_CASH_INFO n ON n.FINPROD_ID = ''F16_'' || m.PORTFOLIO_ID AND n.CASH_TYPE_1 = ''01'' AND n.CASH_TYPE_2 = ''C01''
  INNER JOIN FIN_OPEN_RULE r ON r.CASH_ID = n.CASH_ID AND r.OPEN_MODE = ''02''
  UNION ALL 
  SELECT PORTFOLIO_ID ,OPEN_VDATE FROM (SELECT m.PORTFOLIO_ID,y.OPEN_VDATE ,rank() over(PARTITION BY m.PORTFOLIO_ID ORDER BY y.OPEN_VDATE asc) AS rowno  from PTL_PORTFOLIO m 
  INNER JOIN  FIN_CASH_INFO n ON n.FINPROD_ID=''F16_''||m.PORTFOLIO_ID  AND n.CASH_TYPE_1=''01'' AND n.CASH_TYPE_2=''C01''
  INNER JOIN  FIN_OPEN_PLAN y ON y.CASH_ID=n.CASH_ID AND y.OPEN_TYPE IN (''02'',''03'')
  INNER JOIN  PA_PTL_PORTFOLIO s   on m.PORTFOLIO_ID=s.PORTFOLIO_ID AND s.OPEN_TYPE=''02''
  WHERE    y.OPEN_VDATE>date''${valDate}''  ORDER BY y.OPEN_VDATE ASC) WHERE  rowno=1', 'portfolioCode', 'N', 'jjpei', '99999', TIMESTAMP '2020-05-20 10:11:48', 'jjpei', TIMESTAMP '2020-05-20 10:11:48');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('TZDYSSGSFXGP', '01', 'SQL', 'SELECT nvl(sum(nvl(RVALUE, 0)),0) as RVALUE,s1.RKEY  FROM (	 
select	 
 sum(nvl(SHARE_AMT,0)) as RVALUE, t1.PORTFOLIO_ID||'',''||t1.FINPROD_ID as RKEY	 
from PTL_SEC_VALUTION t1	 
inner join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID 	 
inner join FIN_PRODUCT_TYPE fpt on t1.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 and (fpt.TYPE_8 =''F11''  OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B17''))	 
where  t1.CDATE = date''${valDate}''-1	 
group by t1.PORTFOLIO_ID,t1.FINPROD_ID,t2.FINPROD_NAME	 
UNION ALL	 
  select sum(nvl(SHARE_AMT,0)) as RVALUE, s2.PTL_BAG_ID||'',''||s1.FINPROD_ID as RKEY	 
 from (select t1.*	 
from PTL_SEC_VALUTION t1	 
inner join FIN_PRODUCT t2 on t1.FINPROD_ID = t2.FINPROD_ID 	 
inner join FIN_PRODUCT_TYPE fpt on t1.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 and (fpt.TYPE_8 =''F11''  OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B17''))	 
where  t1.CDATE = date''${valDate}''-1	 
) s1,( select t1.PORTFOLIO_ID,t1.PTL_BAG_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}''-1 )	 
s2 where s1.PORTFOLIO_ID=s2.PORTFOLIO_ID  group by s2.PTL_BAG_ID,s1.FINPROD_ID	 
 ) s1 group by s1.RKEY', 'portfolioCode,assetCode', 'N', 'GY', '001', TIMESTAMP '2020-05-13 11:08:24', 'GY', TIMESTAMP '2020-05-13 11:08:24');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('TZDYSSGSFXGP', '05', 'SQL', 'select nvl(sum(nvl(SHARE_AMT,0)),0) as RVALUE, t1.FINPROD_ID as RKEY,t2.FINPROD_NAME AS RKEYCN from PTL_SEC_VALUTION t1	
inner join FIN_PRODUCT t2 on t1.FINPROD_ID=t2.FINPROD_ID 	
inner join FIN_PRODUCT_TYPE fpt on t1.FINPROD_ID=fpt.FINPROD_ID AND fpt.BRANCH=0 and (fpt.TYPE_8 =''F11''  OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B17''))	
where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE=date''${valDate}'' group by t1.FINPROD_ID,t2.FINPROD_NAME', 'portfolioCode,assetCode', 'N', 'GY', '001', TIMESTAMP '2020-05-13 11:08:24', 'GY', TIMESTAMP '2020-05-13 11:08:24');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('FBSLCCPDQRHKFSLCCP', '03', 'SQL', 'select n.PORTFOLIO_ID RKEY,MDATE as RVALUE from PTL_PORTFOLIO m INNER JOIN PA_PTL_PORTFOLIO n 
  ON m.PORTFOLIO_ID=n.PORTFOLIO_ID AND n.OPEN_TYPE=''01'' 
  UNION ALL
  select n.PORTFOLIO_ID RKEY,MDATE as RVALUE from PTL_PORTFOLIO m 
  INNER JOIN PA_PTL_PORTFOLIO n ON m.PORTFOLIO_ID=n.PORTFOLIO_ID AND n.OPEN_TYPE=''02''
  INNER JOIN FIN_CASH_INFO n ON n.FINPROD_ID = ''F16_'' || m.PORTFOLIO_ID AND n.CASH_TYPE_1 = ''01'' AND n.CASH_TYPE_2 = ''C01''
  INNER JOIN FIN_OPEN_RULE r ON r.CASH_ID = n.CASH_ID AND r.OPEN_MODE = ''02'' 
  UNION ALL 
  SELECT PORTFOLIO_ID ,OPEN_VDATE FROM (SELECT m.PORTFOLIO_ID,y.OPEN_VDATE ,rank() over(PARTITION BY m.PORTFOLIO_ID ORDER BY y.OPEN_VDATE asc) AS rowno  from PTL_PORTFOLIO m 
  INNER JOIN  FIN_CASH_INFO n ON n.FINPROD_ID=''F16_''||m.PORTFOLIO_ID  AND n.CASH_TYPE_1=''01'' AND n.CASH_TYPE_2=''C01''
  INNER JOIN  FIN_OPEN_PLAN y ON y.CASH_ID=n.CASH_ID AND y.OPEN_TYPE IN (''02'',''03'')
  INNER JOIN  PA_PTL_PORTFOLIO s   on m.PORTFOLIO_ID=s.PORTFOLIO_ID AND s.OPEN_TYPE=''02''
  WHERE    y.OPEN_VDATE>date''${valDate}''  ORDER BY y.OPEN_VDATE ASC) WHERE  rowno=1', 'portfolioCode', 'N', 'jjpei', '99999', TIMESTAMP '2020-05-20 10:11:48', 'jjpei', TIMESTAMP '2020-05-20 10:11:48');
  
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('FBSLCCPDQRHKFSLCCP', '02', 'SQL', 'select n.PORTFOLIO_ID RKEY,MDATE as RVALUE from PTL_PORTFOLIO m INNER JOIN PA_PTL_PORTFOLIO n 
  ON m.PORTFOLIO_ID=n.PORTFOLIO_ID AND n.OPEN_TYPE=''01'' 
  UNION ALL 
  select n.PORTFOLIO_ID RKEY,MDATE as RVALUE from PTL_PORTFOLIO m 
  INNER JOIN PA_PTL_PORTFOLIO n ON m.PORTFOLIO_ID=n.PORTFOLIO_ID AND n.OPEN_TYPE=''02''
  INNER JOIN FIN_CASH_INFO n ON n.FINPROD_ID = ''F16_'' || m.PORTFOLIO_ID AND n.CASH_TYPE_1 = ''01'' AND n.CASH_TYPE_2 = ''C01''
  INNER JOIN FIN_OPEN_RULE r ON r.CASH_ID = n.CASH_ID AND r.OPEN_MODE = ''02''  
  UNION ALL 
  SELECT PORTFOLIO_ID ,OPEN_VDATE FROM (SELECT m.PORTFOLIO_ID,y.OPEN_VDATE ,rank() over(PARTITION BY m.PORTFOLIO_ID ORDER BY y.OPEN_VDATE asc) AS rowno  from PTL_PORTFOLIO m 
  INNER JOIN  FIN_CASH_INFO n ON n.FINPROD_ID=''F16_''||m.PORTFOLIO_ID  AND n.CASH_TYPE_1=''01'' AND n.CASH_TYPE_2=''C01''
  INNER JOIN  FIN_OPEN_PLAN y ON y.CASH_ID=n.CASH_ID AND y.OPEN_TYPE IN (''02'',''03'')
  INNER JOIN  PA_PTL_PORTFOLIO s   on m.PORTFOLIO_ID=s.PORTFOLIO_ID AND s.OPEN_TYPE=''02''
  WHERE    y.OPEN_VDATE>date''${valDate}''  ORDER BY y.OPEN_VDATE ASC) WHERE  rowno=1', 'portfolioCode', 'N', 'jjpei', '99999', TIMESTAMP '2020-05-20 10:11:48', 'jjpei', TIMESTAMP '2020-05-20 10:11:48');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('FSMCPBDTZWSSQYGQ', '04', 'SQL', 'SELECT	
	t3.RAISE_TYPE || t3.OPEN_TYPE AS RVALUE,t3.ITEM_VALUE||t3.ITEM_VALUE2 as RKEY
FROM TRD_PRODUCT_DEAL t0	
inner join TRD_PRODUCT_DEAL_ADD t1  on t0.TRADE_ID = t1.TRADE_ID	
INNER JOIN FIN_PRODUCT_TYPE t2 ON t0.FINPROD_ID=t2.FINPROD_ID AND t2.BRANCH=0 AND t2.TYPE_8=''F06'' AND TYPE_6=''P02'' AND t2.TYPE_11=''084'' 	
LEFT join	(SELECT m.PORTFOLIO_ID,n.RAISE_TYPE,n.OPEN_TYPE,y1.ITEM_VALUE,y2.ITEM_VALUE AS ITEM_VALUE2 FROM PTL_PORTFOLIO m 
	INNER JOIN PA_PTL_PORTFOLIO n ON m.PORTFOLIO_ID = n.PORTFOLIO_ID
	LEFT JOIN SYS_DATADICT_LIST y1 on n.RAISE_TYPE=y1.ITEM_CODE and y1.DICT_CODE=''RAISE_TYPE''
	LEFT JOIN SYS_DATADICT_LIST y2 on n.OPEN_TYPE=y2.ITEM_CODE and y2.DICT_CODE=''ISSUE_MODE''
	) t3 ON t1.PORTFOLIO_ID=t3.PORTFOLIO_ID
WHERE	t1.PORTFOLIO_ID IN ${portfolioCode} AND  t0.TRADE_DATE =date''${valDate}''
UNION ALL	
SELECT	
	t3.RAISE_TYPE || t3.OPEN_TYPE AS RVALUE,t3.ITEM_VALUE||t3.ITEM_VALUE2 as RKEY
FROM WFL_TRD_PRODUCT_DEAL t0	
inner join WFL_TRD_PRODUCT_DEAL_ADD t1  on t0.TRADE_ID = t1.TRADE_ID and t0.TRADE_STATUS != ''03''	
INNER JOIN FIN_PRODUCT_TYPE t2 ON t0.FINPROD_ID=t2.FINPROD_ID AND t2.BRANCH=0 AND t2.TYPE_8=''F06'' AND TYPE_6=''P02'' AND t2.TYPE_11=''084'' 	
LEFT join	(SELECT m.PORTFOLIO_ID,n.RAISE_TYPE,n.OPEN_TYPE,y1.ITEM_VALUE,y2.ITEM_VALUE AS ITEM_VALUE2 FROM PTL_PORTFOLIO m 
	INNER JOIN PA_PTL_PORTFOLIO n ON m.PORTFOLIO_ID = n.PORTFOLIO_ID
	LEFT JOIN SYS_DATADICT_LIST y1 on n.RAISE_TYPE=y1.ITEM_CODE and y1.DICT_CODE=''RAISE_TYPE''
	LEFT JOIN SYS_DATADICT_LIST y2 on n.OPEN_TYPE=y2.ITEM_CODE and y2.DICT_CODE=''ISSUE_MODE''
	) t3 ON t1.PORTFOLIO_ID=t3.PORTFOLIO_ID
WHERE	t1.PORTFOLIO_ID IN ${portfolioCode} AND  t0.TRADE_DATE =date''${valDate}''', 'portfolioCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-06 10:48:53', 'jjpei', TIMESTAMP '2020-05-06 10:48:53');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('FSMCPBDTZWSSQYGQ', '05', 'SQL', 'SELECT	
	t3.RAISE_TYPE || t3.OPEN_TYPE AS RVALUE,t3.ITEM_VALUE||t3.ITEM_VALUE2 as RKEY
FROM PTL_SEC_VALUTION t1	
INNER JOIN FIN_PRODUCT_TYPE t2 ON t1.FINPROD_ID=t2.FINPROD_ID AND t2.BRANCH=0 AND t2.TYPE_8=''F06'' AND TYPE_6=''P02'' AND t2.TYPE_11=''084'' 	
LEFT join	(SELECT m.PORTFOLIO_ID,n.RAISE_TYPE,n.OPEN_TYPE,y1.ITEM_VALUE,y2.ITEM_VALUE AS ITEM_VALUE2 FROM PTL_PORTFOLIO m 
	INNER JOIN PA_PTL_PORTFOLIO n ON m.PORTFOLIO_ID = n.PORTFOLIO_ID
	LEFT JOIN SYS_DATADICT_LIST y1 on n.RAISE_TYPE=y1.ITEM_CODE and y1.DICT_CODE=''RAISE_TYPE''
	LEFT JOIN SYS_DATADICT_LIST y2 on n.OPEN_TYPE=y2.ITEM_CODE and y2.DICT_CODE=''ISSUE_MODE''
	) t3 ON t1.PORTFOLIO_ID=t3.PORTFOLIO_ID
WHERE	t1.PORTFOLIO_ID IN ${portfolioCode} AND  t1.CDATE =date''${valDate}''', 'portfolioCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-06 10:48:53', 'jjpei', TIMESTAMP '2020-05-06 10:48:53');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('FBSLCCPDQRHKFSLCCP', '04', 'SQL', 'select ceil(MDATE-date''${valDate}'') as mdate from PTL_PORTFOLIO m INNER JOIN PA_PTL_PORTFOLIO n 
  ON m.PORTFOLIO_ID=n.PORTFOLIO_ID AND n.OPEN_TYPE=''01'' where n.PORTFOLIO_ID in ${portfolioCode}
