  select ceil(MDATE-date''${valDate}'') as mdate from PTL_PORTFOLIO m 
  INNER JOIN PA_PTL_PORTFOLIO n ON m.PORTFOLIO_ID=n.PORTFOLIO_ID AND n.OPEN_TYPE=''02'' 
  INNER JOIN FIN_CASH_INFO n ON n.FINPROD_ID = ''F16_'' || m.PORTFOLIO_ID AND n.CASH_TYPE_1 = ''01'' AND n.CASH_TYPE_2 = ''C01''
  INNER JOIN FIN_OPEN_RULE r ON r.CASH_ID = n.CASH_ID AND r.OPEN_MODE = ''02''
  where n.PORTFOLIO_ID in ${portfolioCode} 
  UNION ALL 
  SELECT mdate FROM (SELECT ceil(y.OPEN_VDATE-date''${valDate}'') as mdate  from PTL_PORTFOLIO m 
  INNER JOIN  FIN_CASH_INFO n ON n.FINPROD_ID=''F16_''||m.PORTFOLIO_ID  AND n.CASH_TYPE_1=''01'' AND n.CASH_TYPE_2=''C01''
  INNER JOIN  FIN_OPEN_PLAN y ON y.CASH_ID=n.CASH_ID AND y.OPEN_TYPE IN (''02'',''03'')
  INNER JOIN  PA_PTL_PORTFOLIO s   on m.PORTFOLIO_ID=s.PORTFOLIO_ID AND s.OPEN_TYPE=''02''
  WHERE  m.PORTFOLIO_ID in ${portfolioCode} AND  y.OPEN_VDATE>date''${valDate}'' ORDER BY y.OPEN_VDATE ASC) WHERE  rownum=1', 'portfolioCode', 'N', 'jjpei', '99999', TIMESTAMP '2020-05-20 10:11:48', 'jjpei', TIMESTAMP '2020-05-20 10:11:48');
