INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('SPJJRYSPLZCGM', '01', 'SQL', 'select m.PORTFOLIO_ID as RKEY,nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)),0) as  RVALUE from PTL_SEC_VALUTION m	 
INNER JOIN FIN_PRODUCT_ADD PFP	 
on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''03''	 
where  m.CDATE =date''${valDate}''-1  AND m.PORTFOLIO_ID!=m.FINPROD_ID group by m.PORTFOLIO_ID', 'portfolioCode', 'Y', 'GY', '001', TIMESTAMP '2020-05-13 11:01:46', 'GY', TIMESTAMP '2020-05-13 11:01:46');
