INNER JOIN FIN_PRODUCT_ADD PFP	
on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''03''	
where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}'' AND m.PORTFOLIO_ID!=m.FINPROD_ID', 'portfolioCode', 'Y', 'GY', '001', TIMESTAMP '2020-05-13 11:01:46', 'GY', TIMESTAMP '2020-05-13 11:01:46');
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('FBZHZQLZCDYE', '02', 'SQL', 'SELECT RKEY,SUM(RVALUE) RVALUE FROM (			 
select m.PORTFOLIO_ID AS RKEY,nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)),0) as  RVALUE from PTL_SEC_VALUTION m			 
inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID  and ((fpt.TYPE_8 =''F06'' and fpt.TYPE_6 IN(''P01'',''P11'')) OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B18''))			 
where    m.CDATE =date''${valDate}''-1  group by m.PORTFOLIO_ID			 
 union all			 
   select t.PTL_BAG_ID as RKEY,			 
   ( select nvl(sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)),0) as  RVALUE from PTL_SEC_VALUTION m			 
   inner join FIN_PRODUCT_TYPE fpt on m.FINPROD_ID=fpt.FINPROD_ID  and ((fpt.TYPE_8 =''F06'' and fpt.TYPE_6 IN(''P01'',''P11'')) OR (fpt.TYPE_8 =''F01'' and fpt.TYPE_6 =''B18''))			 
	where    m.CDATE =date''${valDate}''-1  AND 		 
	m.PORTFOLIO_ID in (   select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>date''${valDate}'' where t1.PTL_BAG_ID=t.PTL_BAG_ID)		 
   )			 
from RSK_PORTFOLIO_PACKAGE t			 
