INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('GZQSZHZZQTZJJSZ', '04', 'SQL', 'WITH JIJING AS (		 
	SELECT FINPROD_ID,nvl(VALUATION,1)*nvl(C_SHARES,0) AS tradeAmount FROM 	 
		 	(	 
		 	    SELECT s1.FINPROD_ID,CASE s2.TYPE_6 WHEN ''F01'' THEN 1 else VALUATION END VALUATION,C_SHARES, RANK() OVER(PARTITION BY s1.FINPROD_ID ORDER BY s1.VAL_DATE DESC ) AS rowno	 
				FROM FIN_PRODUCT_VALUATION s1 
				LEFT JOIN (SELECT m1.FINPROD_MARKET_ID,m2.TYPE_6 FROM FIN_PRODUCT m1 INNER JOIN FIN_PRODUCT_TYPE m2 ON m1.FINPROD_ID=m2.FINPROD_ID AND m2.BRANCH=0 AND m2.TYPE_8=''F02'') s2 
				ON s1.FINPROD_ID=s2.FINPROD_MARKET_ID 
				WHERE s1.VAL_DATE<=date''${valDate}'' 
			) WHERE rowno=1	 
),		 
 BOND AS (		 
  SELECT SEC_ID,nvl(PRICE,100) PRICE FROM (SELECT SEC_ID,PRICE, RANK() OVER(PARTITION BY SEC_ID ORDER BY VALUE_DATE DESC ) AS rowno		 
		FROM MST_BOND_VALUATION_INFO WHERE VALUE_DATE<=date''${valDate}'') WHERE rowno=1 
)		 
SELECT DISTINCT RVALUE,RKEY,RKEYCN FROM (		 
	SELECT nvl(t2.ISSUE_AMT,0)*nvl(BOND.PRICE,100)/100 AS RVALUE,	 
	T2.FINPROD_ID RKEY,t2.FINPROD_NAME RKEYCN FROM PTL_SEC_VALUTION T1	 
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F01''	 
	LEFT JOIN BOND ON t2.FINPROD_MARKET_ID=BOND.SEC_ID	 
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND t1.CDATE=date''${valDate}''-1	 
UNION ALL		 
	SELECT RVALUE,RKEY,RKEYCN FROM (	 
	SELECT JIJING.tradeAmount RVALUE,	 
    T2.FINPROD_ID RKEY,		 
	t2.FINPROD_NAME RKEYCN FROM PTL_SEC_VALUTION T1	 
	INNER JOIN FIN_PRODUCT t2 ON t1.FINPROD_ID=t2.FINPROD_ID AND T2.FINPROD_TYPE2 =''F06''	 
	LEFT JOIN  JIJING ON t2.FINPROD_MARKET_ID=JIJING.FINPROD_ID	 
	WHERE t1.PORTFOLIO_ID IN ${portfolioCode} AND t1.CDATE=date''${valDate}''-1	 
	)	', 'assetCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-05 14:23:24', 'jjpei', TIMESTAMP '2020-05-05 14:23:24');
