	LEFT JOIN FIN_PRODUCT_TYPE FIN_PRODUCT_TYPE2 ON TRD_PRODUCT_DEAL.FINPROD_ID = FIN_PRODUCT_TYPE2.FINPROD_ID 
	LEFT JOIN FIN_PRODUCT_ADD FIN_PRODUCT_ADD2 ON FIN_PRODUCT_ADD2.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID 
	LEFT JOIN TRD_PRODUCT_DEAL TRD_PRODUCT_DEAL2 ON TRD_PRODUCT_DEAL2.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID 
	LEFT JOIN REP_ASSET_DEPT REP_ASSET_DEPT2 ON TRD_PRODUCT_DEAL.FINPROD_ID = REP_ASSET_DEPT2.REP_FINPROD_ID 
	LEFT JOIN (SELECT * FROM (SELECT O_CODE,GRADE_RESULT,ROW_NUMBER() OVER(PARTITION BY O_CODE ORDER BY CREATE_TIME desc) AS rn FROM MST_BOND_CREDIT_RATING T WHERE O_TYPE = ''02'' AND GRADE_DATE<=DATE ''${valDate}'') where rn=1 ) ZXRATING2 ON ZXRATING2.O_CODE = TRD_PRODUCT_DEAL.FINPROD_ID 
