	ZTRATING2.GRADE_RESULT bodyGradeType, 
	DTL.PTL_BAG_ID portfolioId, 
	FIN_PRODUCT2.MDATE mdate 
	FROM PTL_SEC_VALUTION PTL_SEC_VALUTION2 
	LEFT JOIN FIN_PRODUCT FIN_PRODUCT2 ON PTL_SEC_VALUTION2.FINPROD_ID = FIN_PRODUCT2.FINPROD_ID 
	LEFT JOIN (SELECT s1.*,s2.INDUSTRY,s2.INDUSTRY2 FROM MST_CUSTOMER_INFO s1 INNER JOIN MST_CUSTOMER_INFO_ADD s2 ON s1.CUSTOMER_ID=s2.CUSTOMER_ID) MST_CUSTOMER_INFO2 ON FIN_PRODUCT2.ISSUER = MST_CUSTOMER_INFO2.CUSTOMER_ID 
	LEFT JOIN FIN_PRODUCT_TYPE FIN_PRODUCT_TYPE2 ON PTL_SEC_VALUTION2.FINPROD_ID = FIN_PRODUCT_TYPE2.FINPROD_ID 
	LEFT JOIN FIN_PRODUCT_ADD FIN_PRODUCT_ADD2 ON FIN_PRODUCT_ADD2.FINPROD_ID = PTL_SEC_VALUTION2.FINPROD_ID 
	LEFT JOIN REP_ASSET_DEPT REP_ASSET_DEPT2 ON PTL_SEC_VALUTION2.FINPROD_ID = REP_ASSET_DEPT2.REP_FINPROD_ID 
	LEFT JOIN (SELECT * FROM (SELECT O_CODE,GRADE_RESULT,ROW_NUMBER() OVER(PARTITION BY O_CODE ORDER BY CREATE_TIME desc) AS rn FROM MST_BOND_CREDIT_RATING T WHERE O_TYPE = ''02'' AND GRADE_DATE<=DATE ''${valDate}'') where rn=1 ) ZXRATING2 ON ZXRATING2.O_CODE = PTL_SEC_VALUTION2.FINPROD_ID 
	LEFT JOIN (SELECT * FROM (SELECT O_CODE,GRADE_DATE,GRADE_RESULT,ROW_NUMBER() OVER(PARTITION BY O_CODE ORDER BY CREATE_TIME desc) AS rn FROM MST_BOND_CREDIT_RATING T WHERE O_TYPE = ''01'' AND GRADE_DATE<=DATE ''${valDate}'') where rn=1 ) ZTRATING2 ON ZTRATING2.O_CODE = PTL_SEC_VALUTION2.FINPROD_ID 
	LEFT JOIN RSK_PORTFOLIO_PACKAGE_DTL DTL ON DTL.PORTFOLIO_ID = PTL_SEC_VALUTION2.PORTFOLIO_ID 
	WHERE  PTL_SEC_VALUTION2.CDATE = DATE ''${valDate}''-1  
	and PTL_SEC_VALUTION2.PORTFOLIO_ID in (select t1.PORTFOLIO_ID from RSK_PORTFOLIO_PACKAGE_DTL t1  inner join PTL_PORTFOLIO t2 on t1.PORTFOLIO_ID=t2.PORTFOLIO_ID and t2.MDATE>=date''${valDate}'') 
	GROUP BY	DTL.PTL_BAG_ID,FIN_PRODUCT_TYPE2.TYPE_4,FIN_PRODUCT_TYPE2.TYPE_5,FIN_PRODUCT_TYPE2.TYPE_6,FIN_PRODUCT_TYPE2.TYPE_7,FIN_PRODUCT_ADD2.INVEST_NATURE, REP_ASSET_DEPT2.REP_ASSET_TYPE,	PTL_SEC_VALUTION2.FINPROD_ID,FIN_PRODUCT2.ISSUER,MST_CUSTOMER_INFO2.INDUSTRY,MST_CUSTOMER_INFO2.INDUSTRY2,ZXRATING2.GRADE_RESULT,ZTRATING2.GRADE_RESULT,FIN_PRODUCT2.MDATE'  where PARA_CODE = 'FHMB' and PARA_GRANULARITY='02';
	 
	INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('ZHKTZZCXZ', '04', 'SQL', 'with tmp as (select 											 
case when assetType=''F01'' then ''PINAN_ASSET_TYPE,WINDTYPEONE,WINDTYPETWO''											 
when  assetType=''F02'' then ''PINAN_ASSET_TYPE,FUND_ASSET_TYPE,FUND_ASSET_SECOND_TYPE''											 
when  assetType=''F06'' then ''PINAN_ASSET_TYPE,ASSET_TYPE_PROJECT,ASSET_TYPE_PROJECT_TWO''											 
when  assetType=''F05'' then ''PINAN_ASSET_TYPE,DEPO_ASSET_TYPE,DEPO_TYPE''											 
else ''PINAN_ASSET_TYPE'' end ITEMCODE,assetMxType as VALUE											 
from (											 
	select DISTINCT assetType, case when assetMxType is null then assetType else assetMxType end as assetMxType from (										 
		select 									 
			 t4.TYPE_8 as assetType,								 
			CASE WHEN TYPE_8 IN(''F01'',''F02'',''F06'') THEN TYPE_8||''_''||TYPE_6								 
			     WHEN TYPE_8 =''F05'' THEN (								 
			     CASE WHEN TYPE_7 IS NOT NULL THEN TYPE_8||''_''||TYPE_7								 
			     ELSE TYPE_8||''_''||TYPE_6 END )								 
			END AS assetMxType 								 
		from PTL_SEC_VALUTION t1									 
		inner join FIN_PRODUCT_TYPE t4 on t1.FINPROD_ID = t4.FINPROD_ID									 
		where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE = date''${valDate}''-1									 
		union all 									 
		select 									 
		 t4.TYPE_8 as assetType,t4.TYPE_8 as assetMxType									 
		from PTL_SEC_VALUTION t1									 
		inner join FIN_TRADE_PRODUCT t2	 on t1.FINPROD_ID = t2.FINPROD_ID								 
		inner join FIN_PRODUCT_TYPE t4 on t1.FINPROD_ID = t4.FINPROD_ID									 
		where t1.PORTFOLIO_ID in ${portfolioCode} and  t1.CDATE = date''${valDate}''-1									 
		union all 									 
		 SELECT									 
		  t4.TYPE_8 as assetType,									 
			CASE WHEN TYPE_8 IN(''F01'',''F02'',''F06'') THEN TYPE_8||''_''||TYPE_6								 
			     WHEN TYPE_8 =''F05'' THEN (								 
			     CASE WHEN TYPE_7 IS NOT NULL THEN TYPE_8||''_''||TYPE_7								 
			     ELSE TYPE_8||''_''||TYPE_6 END )								 
			END AS assetMxType								 
		  from TRD_PRODUCT_DEAL n									 
		   inner join TRD_PRODUCT_DEAL_ADD t1  on n.TRADE_ID = t1.TRADE_ID									 
		   inner join FIN_PRODUCT t2  on n.FINPROD_ID = t2.FINPROD_ID									 
		  left join FIN_PRODUCT_TYPE t4 on t2.FINPROD_ID = t4.FINPROD_ID									 
		  where t1.PORTFOLIO_ID in ${portfolioCode} and  n.TRADE_DATE=date''${valDate}''', 'portfolioCode', 'N', 'admin', '001', TIMESTAMP '2020-05-19 15:38:45', 'admin', TIMESTAMP '2020-05-19 15:38:46');									 
	     ---------过长截断
		 update RSK_ISUP_INDICATOR_PARA_DTL set content = content||' union all 									 
		 SELECT									 
		  t4.TYPE_8 as assetType,t4.TYPE_8 as assetMxType									 
		  from TRD_PRODUCT_DEAL n									 
		   inner join TRD_PRODUCT_DEAL_ADD t1  on n.TRADE_ID = t1.TRADE_ID									 
		  inner join FIN_TRADE_PRODUCT t2 on n.FINPROD_ID = t2.FINPROD_ID AND t2.BRANCH=0									 
		  inner join FIN_PRODUCT_TYPE t4 on n.FINPROD_ID = t4.FINPROD_ID									 
		  where t1.PORTFOLIO_ID in ${portfolioCode} and  n.TRADE_DATE=date''${valDate}''									 
		  									 
		   union all 									
		 SELECT									
		  t4.TYPE_8 as assetType,									
			CASE WHEN TYPE_8 IN(''F01'',''F02'',''F06'') THEN TYPE_8||''_''||TYPE_6								
			     WHEN TYPE_8 =''F05'' THEN (								
			     CASE WHEN TYPE_7 IS NOT NULL THEN TYPE_8||''_''||TYPE_7								
			     ELSE TYPE_8||''_''||TYPE_6 END )								
			END AS assetMxType								
		   from WFL_TRD_PRODUCT_DEAL_ADD m									
  			inner join WFL_TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID and n.TRADE_STATUS != ''03''								
		   inner join FIN_PRODUCT t2  on n.FINPROD_ID = t2.FINPROD_ID									
		  left join FIN_PRODUCT_TYPE t4 on t2.FINPROD_ID = t4.FINPROD_ID									
		  where m.PORTFOLIO_ID in ${portfolioCode} and  n.TRADE_DATE=date''${valDate}''									
		  									
		 union all 									
		 SELECT									
		 t4.TYPE_8 as assetType,t4.TYPE_8 as assetMxType									
		   from WFL_TRD_PRODUCT_DEAL_ADD m									
  			inner join WFL_TRD_PRODUCT_DEAL n on m.TRADE_ID=n.TRADE_ID and n.TRADE_STATUS != ''03''								
		  inner join FIN_TRADE_PRODUCT t2 on n.FINPROD_ID = t2.FINPROD_ID AND t2.BRANCH=0									
		   inner join FIN_PRODUCT_TYPE t4 on n.FINPROD_ID = t4.FINPROD_ID									
		  where m.PORTFOLIO_ID in ${portfolioCode} and  n.TRADE_DATE=date''${valDate}''									
	 ) 										
    ) t											
) 											
select DISTINCT m.VALUE RVALUE,n.ITEM_VALUE as RKEY from tmp m left join (											
				select DICT_CODE,''F01_''||ITEM_CODE AS ITEM_CODE,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''WINDTYPEONE''							
				union all							
				select DICT_CODE,''F02_''||ITEM_CODE ,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''FUND_ASSET_TYPE''							
				union all							
				select DICT_CODE,''F05_''||ITEM_CODE ,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''DEPO_TYPE''							
				union all							
				select DICT_CODE,''F05_''||ITEM_CODE ,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''DEPO_ASSET_TYPE''							
				union all							
				select DICT_CODE,''F06_''||ITEM_CODE ,ITEM_VALUE  from SYS_DATADICT_LIST where DICT_CODE=''ASSET_TYPE_PROJECT''							
				UNION ALL 							
				SELECT DICT_CODE,ITEM_CODE,ITEM_VALUE FROM SYS_DATADICT_LIST WHERE DICT_CODE  IN (''PINAN_ASSET_TYPE'',''WINDTYPETWO'',''FUND_ASSET_SECOND_TYPE'',''ASSET_TYPE_PROJECT_TWO'')							
	) n on m.VALUE=n.ITEM_CODE 	WHERE m.VALUE IS NOT NULL'  where PARA_CODE = 'ZHKTZZCXZ' and PARA_GRANULARITY='04';
INSERT INTO RSK_ISUP_INDICATOR_PARA_DTL (PARA_CODE, PARA_GRANULARITY, PARA_DISPLAY_TYPE, CONTENT, REDIS_FIELD, IS_FRESH_CAN_TRD, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) VALUES ('CPZCLZCGM', '04', 'SQL', 'select sum(TRADE_AMT) as tradeAmt from		 
 (		 
select sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)) as TRADE_AMT from PTL_SEC_VALUTION m		 
  INNER JOIN FIN_PRODUCT_ADD PFP		 
  on m.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''01''		 
where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}''-1 	 AND m.PORTFOLIO_ID!=m.FINPROD_ID	 
union all		 
select		 
  sum(nvl(DSC_COST_AMT,0)+nvl(TDY_FLOAT_INGPL,0)+nvl(TDY_INTINCEXP,0)+ nvl(DELAY_PAY_AMT,0)) as  TRADE_AMT from PTL_SEC_VALUTION m		 
INNER JOIN FIN_TRADE_PRODUCT n on m.FINPROD_ID = n.FINPROD_ID and n.FINPROD_TYPE2 in (''F03'',''F05'',''F09'') AND n.BRANCH=0		 
where m.PORTFOLIO_ID in ${portfolioCode}  and  m.CDATE =date''${valDate}''-1		 
union ALL		 
  select		 
  nvl(sum(decode(n.PS,''T01'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		 
  +nvl(sum(decode(n.PS,''T04'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 
  +nvl(sum(decode(n.PS,''T20'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 
  +nvl(sum(decode(n.PS,''T52'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		 
  -nvl(sum(decode(n.PS,''T02'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		 
  -nvl(sum(decode(n.PS,''T03'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		 
  -nvl(sum(decode(n.PS,''T06'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) 		 
  -nvl(sum(decode(n.PS,''T08'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		 
  -nvl(sum(decode(n.PS,''T09'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		 
  -nvl(sum(decode(n.PS,''T11'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) 
  -nvl(sum(decode(n.PS,''T19'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) 
  -nvl(sum(decode(n.PS,''T21'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) 
  -nvl(sum(decode(n.PS,''T38'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) 
  -nvl(sum(decode(n.PS,''T39'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) 
  -nvl(sum(decode(n.PS,''T54'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)
  -nvl(sum(decode(n.PS,''T22'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) 
  -nvl(sum(decode(n.PS,''T23'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)  as  TRADE_AMT		 
  from  TRD_PRODUCT_DEAL n		 
  INNER JOIN FIN_TRADE_PRODUCT t2 on t2.FINPROD_ID=n.FINPROD_ID and t2.FINPROD_TYPE2 in (''F03'',''F05'',''F09'')	AND t2.BRANCH=0	 
  LEFT JOIN TRD_PRODUCT_DEAL_ADD n1 ON n.TRADE_ID =n1.TRADE_ID		 
  where n1.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T01'',''T02'',''T03'',''T04'',''T06'',''T07'',''T08'',''T09'',''T11'', 
  ''T19'',''T20'',''T21'',''T38'',''T39'',''T52'',''T54'',''T22'',''T23'')	', 'portfolioCode', 'N', 'jjpei', '2222222', TIMESTAMP '2020-05-14 11:23:29', 'jjpei', TIMESTAMP '2020-05-14 11:23:29');	
---------过长截断
update RSK_ISUP_INDICATOR_PARA_DTL set content = content||'  union ALL 
  SELECT		 
     nvl(sum(decode(n.PS,''T01'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		 
  +nvl(sum(decode(n.PS,''T04'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 
  +nvl(sum(decode(n.PS,''T20'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 
  +nvl(sum(decode(n.PS,''T52'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		 
  -nvl(sum(decode(n.PS,''T02'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		 
  -nvl(sum(decode(n.PS,''T03'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		 
  -nvl(sum(decode(n.PS,''T06'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)	 	 
  -nvl(sum(decode(n.PS,''T08'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		 
  -nvl(sum(decode(n.PS,''T09'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)		 
  -nvl(sum(decode(n.PS,''T11'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) 
  -nvl(sum(decode(n.PS,''T19'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) 
  -nvl(sum(decode(n.PS,''T21'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) 
  -nvl(sum(decode(n.PS,''T38'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) 
  -nvl(sum(decode(n.PS,''T39'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) 
  -nvl(sum(decode(n.PS,''T54'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)
  -nvl(sum(decode(n.PS,''T22'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0) 
  -nvl(sum(decode(n.PS,''T23'',decode(TRADE_STATUS,''03'',n.TRADE_AMT*-1,n.TRADE_AMT))),0)  as  TRADE_AMT	 
  from TRD_PRODUCT_DEAL n		 
    INNER JOIN FIN_PRODUCT_ADD PFP		 
   on n.FINPROD_ID = PFP.FINPROD_ID and PFP.INVEST_NATURE =''01''		 
   LEFT JOIN TRD_PRODUCT_DEAL_ADD n1 ON n.TRADE_ID =n1.TRADE_ID		 
  where n1.PORTFOLIO_ID in ${portfolioCode} and n.TRADE_DATE=date''${valDate}'' and n.PS in (''T01'',''T02'',''T03'',''T04'',''T06'',''T07'',''T08'',''T09'',''T11'', 
